window.AP_US_HISTORY_DECKS = [{"id":"apush-period-1","name":"AP U.S. History · Period 1: 1491–1607","shortName":"Period 1: 1491–1607","builtIn":true,"sourceTitle":"Glossary of Key Terms — The American Pageant","sourceUrl":"https://loscosapush.weebly.com/uploads/5/2/4/8/52484185/glossary_of_key_terms_-_american_pageant.pdf","cards":[{"id":"apush-period-1-c1","front":"Acoma, Battle of (1599)","back":"Fought between Spaniards under Don Juan de Oñate and the Pueblo Indians in present-day New Mexico. Spaniards brutally crushed the Pueblo peoples and established the territory as New Mexico in 1609.","sourcePage":23},{"id":"apush-period-1-c2","front":"Aztecs","back":"Native American empire that controlled present-day Mexico until 1521, when they were conquered by Spanish Hernán Cortés. The Aztecs maintained control over their vast empire through a system of trade and tribute, and came to be known for their advances in mathematics and writing, and their use of human sacrifices in religious ceremonies.","sourcePage":8},{"id":"apush-period-1-c3","front":"Black Legend","back":"False notion that Spanish conquerors did little but butcher the Indians and steal their gold in the name of Christ.","sourcePage":24},{"id":"apush-period-1-c4","front":"Cahokia (c. 1100 A.D.)","back":"Mississippian settlement near present-day East St. Louis, home to as many as 25,000 Native Americans.","sourcePage":10},{"id":"apush-period-1-c5","front":"capitalism","back":"Economic system characterized by private property, generally free trade, and open and accessible markets. European colonization of the Americas, and in particular, the discovery of vast bullion deposits, helped bring about Europe’s transition to capitalism.","sourcePage":17},{"id":"apush-period-1-c6","front":"caravel","back":"Small regular vessel with a high deck and three triangular sails. Caravels could sail more closely into the wind, allowing Euro pean sailors to explore the Western shores of Africa, previously made inaccessible due to prevailing winds on the homeward journey.","sourcePage":11},{"id":"apush-period-1-c7","front":"civilization","back":"Form of political society that traditionally combines centralized government with a high degree of ethnic and cultural unity. The Aztec and Inca empires in South America are early examples of civilizations in the New World.","sourcePage":8},{"id":"apush-period-1-c8","front":"Columbian Exchange","back":"The transfer of goods, crops and diseases between New and Old World societies after 1492.","sourcePage":15},{"id":"apush-period-1-c9","front":"conquistadores","back":"Sixteenth-century Spaniards who fanned out across the Americas, from Colorado to Argentina, eventually conquering the Aztec and Incan empires.","sourcePage":17},{"id":"apush-period-1-c10","front":"Edict of Nantes (1598)","back":"Decree issued by the French crown granting limited toleration to French Protestants. Ended religious wars in France and inaugurated a period of French preeminence in Europe and across the Atlantic. Its repeal in 1685 prompted a fresh migration of Protestant Huguenots to North America.","sourcePage":109},{"id":"apush-period-1-c11","front":"encomienda","back":"Spanish government’s policy to “commend,” or give, Indians to certain colonists in return for the promise to Chris tianize them. Part of a broader Spanish effort to subdue Indian tribes in the West Indies and on the North American mainland.","sourcePage":18},{"id":"apush-period-1-c12","front":"Incas","back":"Highly advanced South American civilization that occupied present-day Peru until they were conquered by Spanish forces under Francisco Pizarro in 1532. The Incas developed sophisticated agricultural techniques, such as terrace farming, in order to sustain large, complex societies in the unforgiving Andes Mountains.","sourcePage":8},{"id":"apush-period-1-c13","front":"mestizos","back":"People of mixed Indian and European heritage, notably in Mexico.","sourcePage":22},{"id":"apush-period-1-c14","front":"noche triste (June 30, 1520)","back":"“Sad night”, when the Aztecs attacked Hernán Cortés and his forces in the Aztec capital, Tenochitlán, killing hundreds. Cortés laid siege to the city the following year, precipitating the fall of the Aztec Empire and inaugurating three centuries of Spanish rule.","sourcePage":22},{"id":"apush-period-1-c15","front":"plantation","back":"Large-scale agricultural enterprise growing commercial crops and usually employing coerced or slave labor. European settlers established plantations in Africa, South America, the Caribbean, and the American South.","sourcePage":13},{"id":"apush-period-1-c16","front":"Protestant Reformation (16th Century)","back":"Movement to reform the Catholic Church launched in Germany by Martin Luther. Reformers questioned the authority of the Pope, sought to eliminate the selling of indulgences, and encouraged the translation of the Bible from Latin, which few at the time could read. The reformation was launched in En gland in the 1530s when King Henry VIII broke with the Roman Catholic Church.","sourcePage":27},{"id":"apush-period-1-c17","front":"Roanoke Island (1585)","back":"Sir Walter Raleigh’s failed colonial settlement off the coast of North Carolina.","sourcePage":28},{"id":"apush-period-1-c18","front":"Spanish Armada (1588)","back":"Spanish fleet defeated in the En glish Channel in 1588. The defeat of the Armada marked the beginning of the decline of the Spanish Empire.","sourcePage":29},{"id":"apush-period-1-c19","front":"three-sister farming","back":"Agricultural system employed by North American Indians as early as 1000 a.d.; maize, beans, and squash were grown together to maximize yields.","sourcePage":10},{"id":"apush-period-1-c20","front":"Tordesillas, Treaty of (1494)","back":"Signed by Spain and Portugal, dividing the territories of the New World. Spain received the bulk of territory in the Americas, compensating Portugal with titles to lands in Africa and Asia.","sourcePage":17}],"questions":[],"feynmanPrompts":[{"id":"apush-period-1-f1","prompt":"Native societies before European contact"},{"id":"apush-period-1-f2","prompt":"European exploration and the Columbian Exchange"}]},{"id":"apush-period-2","name":"AP U.S. History · Period 2: 1607–1754","shortName":"Period 2: 1607–1754","builtIn":true,"sourceTitle":"Glossary of Key Terms — The American Pageant","sourceUrl":"https://loscosapush.weebly.com/uploads/5/2/4/8/52484185/glossary_of_key_terms_-_american_pageant.pdf","cards":[{"id":"apush-period-2-c1","front":"Act of Toleration (1649)","back":"Passed in Maryland, it guaranteed toleration to all Chris tians but decreed the death penalty for those, like Jews and atheists, who denied the divinity of Jesus Christ. Ensured that Maryland would continue to attract a high proportion of Catholic migrants throughout the colonial period.","sourcePage":36},{"id":"apush-period-2-c2","front":"antinomianism","back":"Belief that the elect need not obey the law of either God or man; most notably espoused in the colonies by Anne Hutchinson.","sourcePage":51},{"id":"apush-period-2-c3","front":"Arminianism","back":"Belief that salvation is offered to all humans but is conditional on acceptance of God’s grace. Different from Calvinism, which emphasizes predestination and unconditional election.","sourcePage":98},{"id":"apush-period-2-c4","front":"Bacon’s Rebellion (1676)","back":"Uprising of Virginia backcountry farmers and indentured servants led by planter Nathaniel Bacon; initially a response to Governor William Berkeley’s refusal to protect backcountry settlers from Indian attacks, the rebellion eventually grew into a broader conflict between impoverished settlers and the planter elite.","sourcePage":74},{"id":"apush-period-2-c5","front":"Barbados slave code (1661)","back":"First formal statute governing the treatment of slaves, which provided for harsh punishments against offending slaves but lacked penalties for the mistreatment of slaves by masters. Similar statutes were adopted by Southern plantation societies on the North American mainland in the 17th and 18th centuries.","sourcePage":37},{"id":"apush-period-2-c6","front":"Calvinism","back":"Dominant theological credo of the New England Puritans based on the teachings of John Calvin. Calvinists believed in predestination—that only “the elect” were destined for salvation.","sourcePage":46},{"id":"apush-period-2-c7","front":"charter","back":"Legal document granted by a government to some group or agency to implement a stated purpose, and spelling out the attending rights and obligations. British colonial charters guaranteed inhabitants all the rights of En glishmen, which helped solidify colonists’ ties to Britain during the early years of settlement.","sourcePage":30},{"id":"apush-period-2-c8","front":"Congregational Church","back":"Self-governing Puritan congregations without the hierarchical establishment of the Anglican Church.","sourcePage":82},{"id":"apush-period-2-c9","front":"Dominion of New England (1686–1689)","back":"Administrative union created by royal authority, incorporating all of New England, New York, and East and West Jersey. Placed under the rule of Sir Edmund Andros who curbed popular assemblies, taxed residents without their consent and strictly enforced Navigation Laws. Its collapse after the Glorious Revolution in En gland demonstrated colonial opposition to strict royal control.","sourcePage":55},{"id":"apush-period-2-c10","front":"English Civil War (1642–1651)","back":"Armed conflict between royalists and parliamentarians, resulting in the victory of pro-Parliament forces and the execution of Charles I.","sourcePage":54},{"id":"apush-period-2-c11","front":"Fundamental Orders (1639)","back":"Drafted by settlers in the Connecticut River Valley, document was the first “modern constitution” establishing a demo c ratically controlled government. Key features of the document were borrowed for Connecticut’s colonial charter and later, its state constitution.","sourcePage":52},{"id":"apush-period-2-c12","front":"Glorious (or Bloodless) Revolution (1688)","back":"Relatively peaceful overthrow of the unpopular Catholic monarch, James II, replacing him with Dutch-born William III and Mary, daughter of James II. William and Mary accepted increased Parliamentary oversight and new limits on monarchical authority.","sourcePage":55},{"id":"apush-period-2-c13","front":"Great Awakening (1730s and 1740s)","back":"Religious revival that swept the colonies. Participating ministers, most notably Jonathan Edwards and George Whitfield, placed an emphasis on direct, emotive spirituality. A Second Great Awakening arose in the nineteenth century.","sourcePage":98},{"id":"apush-period-2-c14","front":"Great Migration (1630–1642)","back":"Migration of seventy thousand refugees from En gland to the North American colonies, primarily New England and the Caribbean. The twenty thousand migrants who came to Mas sa chu setts largely shared a common sense of purpose—to establish a model Chris tian settlement in the new world.","sourcePage":49},{"id":"apush-period-2-c15","front":"Half-Way Covenant (1662)","back":"Agreement allowing unconverted offspring of church members to baptize their children. It signified a waning of religious zeal among second and third generation Puritans.","sourcePage":83},{"id":"apush-period-2-c16","front":"headright system","back":"Employed in the tobacco colonies to encourage the importation of indentured servants, the system allowed an individual to acquire fifty acres of land if he paid for a laborer’s passage to the colony.","sourcePage":70},{"id":"apush-period-2-c17","front":"Huguenots","back":"French Protestant dissenters, the Huguenots were granted limited toleration under the Edict of Nantes. After King Louis XIV outlawed Protestantism in 1685, many Huguenots fled elsewhere, including to British North America.","sourcePage":109},{"id":"apush-period-2-c18","front":"indentured servants","back":"Migrants who, in exchange for transatlantic passage, bound themselves to a colonial employer for a term of service, typically between four and seven years. Their migration addressed the chronic labor shortage in the colonies and facilitated settlement.","sourcePage":69},{"id":"apush-period-2-c19","front":"Iroquois Confederacy (late 1500s)","back":"Bound together five tribes— the Mohawks, the Oneidas, the Onondagas, the Cayugas, and the Senecas—in the Mohawk Valley of what is now New York State.","sourcePage":42},{"id":"apush-period-2-c20","front":"Jamestown (1607)","back":"First permanent En glish settlement in North America founded by the Virginia Company.","sourcePage":30},{"id":"apush-period-2-c21","front":"jeremiad","back":"Often-fiery sermons lamenting the waning piety of parishioners first delivered in New Eng land in the mid-seventeenth century; named after the doom-saying Old Testament prophet Jeremiah.","sourcePage":83},{"id":"apush-period-2-c22","front":"joint-stock company","back":"Short-term partnership between multiple investors to fund a commercial enterprise; such arrangements were used to fund En gland’s early colonial ventures.","sourcePage":30},{"id":"apush-period-2-c23","front":"King Philip’s War (1675–1676)","back":"Series of assaults by Metacom, King Philip, on En glish settlements in New England. The attacks slowed the westward migration of New Eng land settlers for several decades.","sourcePage":54},{"id":"apush-period-2-c24","front":"Massachusetts Bay Colony (founded in 1630)","back":"Established by nonseparating Puritans, it soon grew to be the largest and most influential of the New England colonies.","sourcePage":49},{"id":"apush-period-2-c25","front":"Mayflower Compact (1620)","back":"Agreement to form a majoritarian government in Plymouth, signed aboard the Mayflower. Created a foundation for self-government in the colony.","sourcePage":47},{"id":"apush-period-2-c26","front":"middle passage","back":"Transatlantic voyage slaves endured between Africa and the colonies. Mortality rates were notoriously high.","sourcePage":74},{"id":"apush-period-2-c27","front":"Molasses Act (1737)","back":"Tax on imported molasses passed by Parliament in an effort to squelch the North American trade with the French West Indies. It proved largely ineffective due to widespread smuggling.","sourcePage":96},{"id":"apush-period-2-c28","front":"Navigation Laws","back":"Series of laws passed, beginning in 1651, to regulate colonial shipping; the acts provided that only Eng lish ships would be allowed to trade in En glish and colonial ports, and that all goods destined for the colonies would first pass through En gland.","sourcePage":55},{"id":"apush-period-2-c29","front":"Pequot War (1636–1638)","back":"Series of clashes between En glish settlers and Pequot Indians in the Connecticut River valley. Ended in the slaughter of the Pequots by the Puritans and their Narragansett Indian allies.","sourcePage":54},{"id":"apush-period-2-c30","front":"Popé’s Rebellion (1680)","back":"Pueblo Indian rebellion which drove Spanish settlers from New Mexico.","sourcePage":23},{"id":"apush-period-2-c31","front":"predestination","back":"Calvinist doctrine that God has foreordained some people to be saved and some to be damned. Though their fate was irreversible, Calvinists, particularly those who believed they were destined for salvation, sought to lead sanctified lives in order to demonstrate to others that they were in fact members of the “elect.”","sourcePage":47},{"id":"apush-period-2-c32","front":"primogeniture","back":"Legal principle that the oldest son inherits all family property or land. Landowner’s younger sons, forced to seek their fortunes elsewhere, pioneered early exploration and settlement of the Americas.","sourcePage":30},{"id":"apush-period-2-c33","front":"proprietary colonies","back":"Colonies—Maryland, Pennsylvania, and Delaware—under the control of local proprietors, who appointed colonial governors.","sourcePage":104},{"id":"apush-period-2-c34","front":"Puritans","back":"En glish Protestant reformers who sought to purify the Church of En gland of Catholic rituals and creeds. Some of the most devout Puritans believed that only “visible saints” should be admitted to church membership.","sourcePage":47},{"id":"apush-period-2-c35","front":"Royal African Company","back":"En glish joint-stock company that enjoyed a state-granted monopoly on the colonial slave trade from 1672 until 1698. The supply of slaves to the North American colonies rose sharply once the company lost its monopoly privileges.","sourcePage":74},{"id":"apush-period-2-c36","front":"royal colonies","back":"Colonies where governors were appointed directly by the King. Though often competent administrators, the governors frequently ran into trouble with colonial legislatures, which resented the imposition of control from across the Atlantic.","sourcePage":104},{"id":"apush-period-2-c37","front":"Salem witch trials (1692–1693)","back":"Series of witchcraft trials launched after a group of adolescent girls in Salem, Mas sa chu setts, claimed to have been bewitched by certain older women of the town. Twenty individuals were put to death before the trials were put to an end by the Governor of Mas sac hu setts.","sourcePage":84},{"id":"apush-period-2-c38","front":"salutary neglect (1688–1763)","back":"Unofficial policy of relaxed royal control over colonial trade and only weak enforcement of Navigation Laws. Lasted from the Glorious Revolution to the end of the French and Indian War in 1763.","sourcePage":56},{"id":"apush-period-2-c39","front":"Separatists","back":"Small group of Puritans who sought to break away entirely from the Church of Eng land; after initially settling in Holland, a number of Eng lish Separatists made their way to Plymouth Bay, Mass a chu setts in 1620.","sourcePage":47},{"id":"apush-period-2-c40","front":"South Carolina slave revolt (Stono River) (1739)","back":"Uprising, also known as the Stono Rebellion, of more than fifty South Carolina blacks along the Stono River. The slaves attempted to reach Spanish Florida but were stopped by the South Carolina militia.","sourcePage":76},{"id":"apush-period-2-c41","front":"squatters","back":"Frontier farmers who illegally occupied land owned by others or not yet officially opened for settlement. Many of North Carolina’s early settlers were squatters, who contributed to the colony’s reputation as being more ind e pen dent-minded and “dem ocratic” than its neighbors.","sourcePage":40},{"id":"apush-period-2-c42","front":"triangular trade","back":"Exchange of rum, slaves, and molasses between the North American Colonies, Africa, and the West Indies. A small but immensely profitable subset of the Atlantic trade.","sourcePage":94},{"id":"apush-period-2-c43","front":"Zenger trial (1734–1735)","back":"New York libel case against John Peter Zenger. Established the principle that truthful statements about public officials could not be prosecuted as libel.","sourcePage":103}],"questions":[],"feynmanPrompts":[{"id":"apush-period-2-f1","prompt":"Regional patterns of British colonization"},{"id":"apush-period-2-f2","prompt":"Atlantic trade and slavery"},{"id":"apush-period-2-f3","prompt":"Colonial society, religion, and self-government"},{"id":"apush-period-2-f4","prompt":"Relations among European settlers and Native nations"}]},{"id":"apush-period-3","name":"AP U.S. History · Period 3: 1754–1800","shortName":"Period 3: 1754–1800","builtIn":true,"sourceTitle":"Glossary of Key Terms — The American Pageant","sourceUrl":"https://loscosapush.weebly.com/uploads/5/2/4/8/52484185/glossary_of_key_terms_-_american_pageant.pdf","cards":[{"id":"apush-period-3-c1","front":"admiralty courts","back":"Used to try offenders for violating the various Navigation Acts passed by the crown after the French and Indian War. Colonists argued that the courts encroached on their rights Englishmen since they lacked juries and placed the burden of proof on the accused.","sourcePage":129},{"id":"apush-period-3-c2","front":"The Age of Reason (1794)","back":"Thomas Paine’s anticlerical treatise that accused churches of seeking to acquire “power and profit” and to “enslave mankind.”","sourcePage":341},{"id":"apush-period-3-c3","front":"Albany Congress (1754)","back":"Intercolonial congress summoned by the British government to foster greater colonial unity and assure Iroquois support in the escalating war against the French.","sourcePage":117},{"id":"apush-period-3-c4","front":"Alien Laws (1798)","back":"Acts passed by a Federalist Congress raising the residency requirement for citizenship to fourteen years and granting the president the power to deport dangerous foreigners in times of peace.","sourcePage":217},{"id":"apush-period-3-c5","front":"antifederalists","back":"Opponents of the 1787 Constitution, they cast the document as antidemocratic, objected to the subordination of the a states to the central government, and feared encroachment on individuals’ liberties in the absence of a bill of rights.","sourcePage":190},{"id":"apush-period-3-c6","front":"Articles of Confederation (1781)","back":"First American constitution that established the United States as a loose confederation of states under a weak national Congress, which was not granted the power to regulate commerce or collect taxes. The Articles were replaced by a more efficient Constitution in 1789.","sourcePage":179},{"id":"apush-period-3-c7","front":"The Association (1774)","back":"Non-importation agreement crafted during the First Continental Congress calling for the complete boycott of British goods.","sourcePage":138},{"id":"apush-period-3-c8","front":"assumption","back":"Transfer of debt from one party to another. In order to strengthen the union, the federal government assumed states’ Revolutionary War debts in 1790, thereby tying the interests of wealthy lenders with those of the national government.","sourcePage":203},{"id":"apush-period-3-c9","front":"Bank of the United States (1791)","back":"Chartered by Congress as part of Alexander Hamilton’s financial program, the bank printed paper money and served as a depository for Treasury funds. It drew opposition from Jeffersonian Republicans, who argued that the bank was unconstitutional.","sourcePage":204},{"id":"apush-period-3-c10","front":"Bill of Rights (1791)","back":"Popular term for the first ten amendments to the U.S. Constitution. The amendments secure key rights for individuals and reserve to the states all powers not explicitly delegated or prohibited by the Constitution.","sourcePage":201},{"id":"apush-period-3-c11","front":"Boston Massacre (1770)","back":"Clash between unruly Bostonian protestors and locally-stationed British redcoats, who fired on the jeering crowd, kill ing or wounding eleven citizens.","sourcePage":133},{"id":"apush-period-3-c12","front":"Boston Tea Party (1773)","back":"Rowdy protest against the British East India Company’s newly acquired monopoly on the tea trade. Colonists, disguised as Indians, dumped 342 chests of tea into Boston harbor, prompting harsh sanctions from the British Parliament.","sourcePage":135},{"id":"apush-period-3-c13","front":"Bunker Hill, Battle of (June 1775)","back":"Fought on the outskirts of Boston, on Breed’s Hill, the battle ended in the colonial militia’s retreat, though at a heavy cost to the British.","sourcePage":147},{"id":"apush-period-3-c14","front":"civic virtue","back":"Willingness on the part of citizens to sacrifice personal self-interest for the public good. Deemed a necessary component of a successful republic.","sourcePage":176},{"id":"apush-period-3-c15","front":"committees of correspondence (1772 and after)","back":"Local committees established across Mas sa chu setts, and later in each of the thirteen colonies, to maintain colonial opposition to British policies through the exchange of letters and pamphlets.","sourcePage":134},{"id":"apush-period-3-c16","front":"Common Sense (1776)","back":"T homas Paine’s pamphlet urging the colonies to declare ind ep end ence and establish a republican government. The widely-read pamphlet helped convince colonists to support the Revolution.","sourcePage":150},{"id":"apush-period-3-c17","front":"cotton gin (1793)","back":"Eli Whitney’s invention that sped up the process of harvesting cotton. The gin made cotton cultivation more profitable, revitalizing the Southern economy and increasing the importance of slav ery in the South.","sourcePage":318},{"id":"apush-period-3-c18","front":"Daughters of Liberty","back":"Patriotic groups that played a central role in agitating against the Stamp Act and enforcing non-importation agreements. (See also Sons of Liberty)","sourcePage":131},{"id":"apush-period-3-c19","front":"Declaration of Independence (July 4, 1776)","back":"Formal pronouncement of ind e pen dence drafted by Thomas Jefferson and approved by Congress. The declaration allowed Americans to appeal for foreign aid and served as an inspiration for later revolutionary movements worldwide.","sourcePage":151},{"id":"apush-period-3-c20","front":"Declaration of the Rights of Man (1789)","back":"Declaration of rights adopted during the French Revolution. Modeled after the American Declaration of Independence.","sourcePage":152},{"id":"apush-period-3-c21","front":"Declaratory Act (1766)","back":"Passed alongside the repeal of the Stamp Act, it reaffirmed Parliament’s unqualified sovereignty over the North American colonies.","sourcePage":132},{"id":"apush-period-3-c22","front":"excise tax","back":"Tax on goods produced domestically. Excise taxes, particularly the 1791 tax on whiskey, were a highly controversial component of Alexander Hamilton’s financial program.","sourcePage":203},{"id":"apush-period-3-c23","front":"Fallen Timbers, Battle of (1794)","back":"Decisive battle between the Miami confederacy and the U.S. Army. British forces refused to shelter the routed Indians, forcing the latter to attain a peace settlement with the United States.","sourcePage":211},{"id":"apush-period-3-c24","front":"Farewell Address (1796)","back":"George Washington’s address at the end of his presidency, warning against “permanent alliances” with other nations. Washington did not oppose all alliances, but believed that the young, fledgling nation should forge alliances only on a temporary basis, in extraordinary circumstances.","sourcePage":213},{"id":"apush-period-3-c25","front":"The Federalist (1788)","back":"Collection of essays written by John Jay, James Madison, and Alexander Hamilton and published during the ratification debate in New York to lay out the Federalists’ arguments in favor of the new Constitution. Since their publication, these influential essays have served as an important source for constitutional interpretation.","sourcePage":193},{"id":"apush-period-3-c26","front":"federalists","back":"Proponents of the 1787 Constitution, they favored a strong national government, arguing that the checks and balances in the new Constitution would safeguard the people’s liberties.","sourcePage":191},{"id":"apush-period-3-c27","front":"First Continental Congress (1774)","back":"Convention of delegates from twelve of the thirteen colonies that convened in Philadelphia to craft a response to the Intolerable Acts. Delegates established Association, which called for a complete boycott of British goods.","sourcePage":137},{"id":"apush-period-3-c28","front":"French and Indian War (Seven Years’ War) (1754–1763)","back":"Nine-year war between the British and the French in North America. It resulted in the expulsion of the French from the North American mainland and helped spark the Seven Years’ War in Europe.","sourcePage":116},{"id":"apush-period-3-c29","front":"funding at par","back":"Payment of debts, such as government bonds, at face value. In 1790, Alexander Hamilton proposed that the federal government pay its Revolutionary war debts in full in order to bolster the nation’s credit.","sourcePage":212},{"id":"apush-period-3-c30","front":"Great Compromise (1787)","back":"Popular term for the measure which reconciled the New Jersey and Virginia plans at the constitutional convention, giving states proportional representation in the House and equal representation in the Senate. The compromise broke stalemate at the convention and paved the way for subsequent compromises over slav ery and the Electoral College.","sourcePage":188},{"id":"apush-period-3-c31","front":"Greenville, Treaty of (1795)","back":"Under the terms of the treaty, the Miami Confederacy agreed to cede territory in the Old Northwest the United States in exchange for cash payment, hunting rights, formal recognition of their sovereign status.","sourcePage":211},{"id":"apush-period-3-c32","front":"“Intolerable Acts” (1774)","back":"Series of punitive meas ures passed in retaliation for the Boston Tea Party, closing the Port of Boston, revoking a number of rights in the Mass ac hus etts colonial charter, and expanding the Quartering Act to allow for the lodging of soldiers in private homes. In response, colonists convened the First Continental Congress and called for a complete boycott of British goods.","sourcePage":136},{"id":"apush-period-3-c33","front":"Jay’s Treaty (1794)","back":"Negotiated by Chief Justice John Jay in an effort to avoid war with Britain, the treaty included a British promise to evacuate outposts on U.S. soil and pay damages for seized American vessels, in exchange for which, Jay bound the United States to repay pre-Revolutionary war debts and to abide by Britain’s restrictive trading policies t oward France.","sourcePage":213},{"id":"apush-period-3-c34","front":"Judiciary Act of 1789","back":"Organized the federal legal system, establishing the Supreme Court, federal district and circuit courts, and the office of the attorney general.","sourcePage":202},{"id":"apush-period-3-c35","front":"Land Ordinance of 1785","back":"Provided for the sale of land in the Old Northwest and earmarked the proceeds toward repaying the national debt.","sourcePage":182},{"id":"apush-period-3-c36","front":"Lexington and Concord, Battles of (April 1775)","back":"First battles of the Revolutionary War, fought outside of Boston. The colonial militia successfully defended their stores of munitions, forcing the British to retreat to Boston.","sourcePage":138},{"id":"apush-period-3-c37","front":"Loyalists","back":"American colonists who opposed the Revolution and maintained their loyalty to the King; sometimes referred to as “Tories.”","sourcePage":156},{"id":"apush-period-3-c38","front":"mercantilism","back":"Economic theory that closely linked a nation’s political and military power to its bullion reserves. Mercantilists generally favored protectionism and colonial acquisition as means to increase exports.","sourcePage":127},{"id":"apush-period-3-c39","front":"Neutrality Proclamation (1793)","back":"Issued by George Washington, it proclaimed America’s formal neutrality in the escalating conflict between En gland and France, a statement that enraged pro-French Jeffersonians.","sourcePage":210},{"id":"apush-period-3-c40","front":"New Jersey Plan (1787)","back":"“Small-state plan” put forth at the Philadelphia convention, proposing equal representation by state, regardless of population, in a unicameral legislature. Small states feared that the more populous states would dominate the agenda under a proportional system.","sourcePage":188},{"id":"apush-period-3-c41","front":"nonimportation agreements (1765 and after)","back":"Boycotts against British goods adopted in response to the Stamp Act and, later, the Townshend and Intolerable Acts. The agreements were the most effective form of protest against British policies in the colonies.","sourcePage":131},{"id":"apush-period-3-c42","front":"Northwest Ordinance (1787)","back":"Created a policy for administering the Northwest Territories. It included a path to statehood and forbade the expansion of slavery into the territories.","sourcePage":182},{"id":"apush-period-3-c43","front":"Olive Branch Petition (July 1775)","back":"Conciliatory measure adopted by the Continental Congress, professing American loyalty and seeking an end to the hostilities. King George rejected the petition and proclaimed the colonies in rebellion.","sourcePage":147},{"id":"apush-period-3-c44","front":"Paris, Treaty of (1783)","back":"Peace treaty signed by Britain and the United States ending the Revolutionary War. The British formally recognized American independence and ceded territory east of Mississippi while the Americans, in turn, promised to restore Loyalist property and repay debts to British creditors.","sourcePage":167},{"id":"apush-period-3-c45","front":"Patriots","back":"colonists who supported the American Revolution; they were also known as “Whigs.”","sourcePage":156},{"id":"apush-period-3-c46","front":"Paxton Boys (1764)","back":"Armed march on Philadelphia by Scotts-Irish frontiersmen in protest against the Quaker establishment’s lenient policies t oward Native Americans.","sourcePage":90},{"id":"apush-period-3-c47","front":"Pinckney’s Treaty (1795)","back":"Signed with Spain which, fearing an Anglo-American alliance, granted Americans free navigation of the Mississippi and the disputed territory of Florida.","sourcePage":213},{"id":"apush-period-3-c48","front":"Pontiac’s uprising (1763)","back":"Bloody campaign waged by Ottawa chief Pontiac to drive the British out of Ohio Country. It was brutally crushed by British troops, who resorted to distributing blankets infected with smallpox as a means to put down the rebellion.","sourcePage":122},{"id":"apush-period-3-c49","front":"Proclamation of 1763","back":"Decree issued by Parliament in the wake of Pontiac’s uprising, prohibiting settlement beyond the Appalachians. Contributed to rising resentment of British rule in the American colonies.","sourcePage":122},{"id":"apush-period-3-c50","front":"Quartering Act (1765)","back":"Required colonies to provide food and quarters for British troops. Many colonists resented the act, which they perceived as an encroachment on their rights.","sourcePage":129},{"id":"apush-period-3-c51","front":"Quebec Act (1774)","back":"Allowed the French residents of Québec to retain their traditional political and religious institutions, and extended the boundaries of the province southward to the Ohio River. Mistakenly perceived by the colonists to be part of Parliament’s response to the Boston Tea Party.","sourcePage":136},{"id":"apush-period-3-c52","front":"Reign of Terror (1793–1794)","back":"Ten-month period of brutal repression when some 40,000 individuals were executed as enemies of the French Revolution. While many Jeffersonians maintained their faith in the French Republic, Federalists withdrew their already lukewarm support once the Reign of Terror commenced.","sourcePage":207},{"id":"apush-period-3-c53","front":"republicanism","back":"Political theory of representative government, based on the principle of popular sovereignty, with a strong emphasis on liberty and civic virtue. Influential in eight eenth-century American political thought, it stood as an alternative to monarchical rule.","sourcePage":126},{"id":"apush-period-3-c54","front":"Saratoga, Battle of (October 1777)","back":"Decisive colonial victory in upstate New York, which helped secure French support for the Revolutionary cause.","sourcePage":160},{"id":"apush-period-3-c55","front":"Second Continental Congress (1775–1781)","back":"Representative body delegates from all thirteen colonies. Drafted the Declaration of Independence and managed the colonial war effort.","sourcePage":146},{"id":"apush-period-3-c56","front":"Sedition Act (1798)","back":"Enacted by the Federalist Congress in an effort to clamp down on Jeffersonian opposition, the law made anyone convicted of defaming government officials or interfering with government policies liable to imprisonment and a heavy fine. The act drew heavy criticism from Republicans, who let the act expire in 1801.","sourcePage":217},{"id":"apush-period-3-c57","front":"Shays’s Rebellion (1786)","back":"Armed uprising of western Mas sa chu setts debtors seeking lower taxes and an end to property foreclosures. Though quickly put down, the insurrection inspired fears of “mob rule” among leading Revolutionaries.","sourcePage":184},{"id":"apush-period-3-c58","front":"Sons of Liberty","back":"Patriotic groups that played a central role in agitating against the Stamp Act and enforcing non-importation agreements. (See also Daughters of Liberty)","sourcePage":131},{"id":"apush-period-3-c59","front":"Stamp Act Congress (1765)","back":"Assembly of delegates from nine colonies who met in New York City to draft a petition for the repeal of the Stamp Act. Helped ease sectional suspicions and promote intercolonial unity.","sourcePage":130},{"id":"apush-period-3-c60","front":"stamp tax (1765)","back":"Widely unpopular tax on an array of paper goods, repealed in 1766 after mass protests erupted across the colonies. Colonists developed the principle of “no taxation without representation” which questioned Parliament’s authority over the colonies and laid the foundation for future revolutionary claims.","sourcePage":129},{"id":"apush-period-3-c61","front":"Sugar Act (1764)","back":"Duty on imported sugar from the West Indies. It was the first tax levied on the colonists by the crown and was lowered substantially in response to widespread protests.","sourcePage":129},{"id":"apush-period-3-c62","front":"three-fifths compromise (1787)","back":"Determined that each slave would be counted as three-fifths of a person for the purpose of apportioning taxes and representation. The compromise granted disproportionate political power to Southern slave states.","sourcePage":189},{"id":"apush-period-3-c63","front":"Townshend Acts (1767)","back":"External, or indirect, levies on glass, white lead, paper, paint and tea, the proceeds of which were used to pay colonial governors, who had previously been paid directly by colonial assemblies. Sparked another round of protests in the colonies.","sourcePage":132},{"id":"apush-period-3-c64","front":"Valley Forge (1777–1778)","back":"Encampment where George Washington’s poorly-equipped army spent a wretched, freezing winter. Hundreds of men died and more than a thousand deserted. The plight of the starving, shivering soldiers reflected the main weakness of the American army—a lack of stable supplies and munitions.","sourcePage":143},{"id":"apush-period-3-c65","front":"Virginia and Kentucky resolutions (1798–1799)","back":"Statements secretly drafted by Jefferson and Madison for the legislatures of Kentucky and Virginia. Argued that states were the final arbiters whether the federal government overstepped its boundaries and could therefore nullify, or refuse to accept, national legislation they deemed unconstitutional.","sourcePage":219},{"id":"apush-period-3-c66","front":"Virginia Plan","back":"“Large state” proposal for the new constitution, calling for proportional representation in both houses of a bicameral Congress. The plan favored larger states and thus prompted smaller states to come back with their own plan for apportioning representation.","sourcePage":188},{"id":"apush-period-3-c67","front":"Virginia Statute for Religious Freedom (1786)","back":"Measure enacted by the Virginia legislature prohibiting state support for religious institutions and recognizing freedom of worship. Served as a model for the religion clause of the first amendment to the Constitution.","sourcePage":175},{"id":"apush-period-3-c68","front":"Whiskey Rebellion (1794)","back":"Popular uprising of whiskey distillers in southwestern Pennsylvania in opposition to an excise tax on whiskey. In a show of strength and resolve by the new central government, Washington put down the rebellion with militia drawn from several states.","sourcePage":204},{"id":"apush-period-3-c69","front":"XYZ Affair (1797)","back":"Diplomatic conflict between France and the United States when American envoys to France were asked to pay a hefty bribe for the privilege of meeting with the French foreign minister. Many in the U.S. called for war against France, while American sailors and privateers waged an undeclared war against French merchants in the Caribbean.","sourcePage":215},{"id":"apush-period-3-c70","front":"Yorktown, Battle of (October 1781)","back":"George Washington, with the aid of the French Army, besieged Cornwallis at Yorktown, while the French naval fleet prevented British reinforcements from coming ashore. Cornwallis surrendered, dealing a heavy blow to the British war effort and paving the way for an eventual peace.","sourcePage":165}],"questions":[],"feynmanPrompts":[{"id":"apush-period-3-f1","prompt":"The imperial crisis and the American Revolution"},{"id":"apush-period-3-f2","prompt":"Creating the Constitution and a new republic"},{"id":"apush-period-3-f3","prompt":"Political parties and debates over federal power"},{"id":"apush-period-3-f4","prompt":"The early republic in an Atlantic world"},{"id":"apush-period-3-f5","prompt":"Causes of the American Revolution"},{"id":"apush-period-3-f6","prompt":"The Articles of Confederation and the Constitution"},{"id":"apush-period-3-f7","prompt":"Federalists and Democratic-Republicans"}]},{"id":"apush-period-4","name":"AP U.S. History · Period 4: 1800–1848","shortName":"Period 4: 1800–1848","builtIn":true,"sourceTitle":"Glossary of Key Terms — The American Pageant","sourceUrl":"https://loscosapush.weebly.com/uploads/5/2/4/8/52484185/glossary_of_key_terms_-_american_pageant.pdf","cards":[{"id":"apush-period-4-c1","front":"Alamo","back":"Fortress in Texas where four hundred American volunteers were slain by Santa Anna in 1836. “Remember the Alamo” became battle cry in support of Texan independence.","sourcePage":294},{"id":"apush-period-4-c2","front":"American Anti-Slavery Society (1833–1870)","back":"Abolitionist society founded by William Lloyd Garrison, who advocated the immediate abolition of slavery. By 1838, the org an iz at ion had more than 250,000 members across 1,350 chapters.","sourcePage":387},{"id":"apush-period-4-c3","front":"American Colonization Society","back":"Reflecting the focus of early abolitionists on transporting freed blacks back to Africa, the or ga ni zation established Liberia, a West-African settlement intended as a haven for emancipated slaves.","sourcePage":384},{"id":"apush-period-4-c4","front":"“The American Scholar” (1837)","back":"Ralph Waldo Emerson’s address at Harvard College, in which he declared an intellectual independence from Europe, urging American scholars to develop their own traditions.","sourcePage":362},{"id":"apush-period-4-c5","front":"American System (1820s)","back":"Henry Clay’s three-pronged system to promote American industry. Clay advocated a strong banking system, a protective tariff and a federally funded transportation network.","sourcePage":256},{"id":"apush-period-4-c6","front":"American Temperance Society","back":"Founded in Boston in 1826 as part of a growing effort of nineteenth-century reformers to limit alcohol consumption.","sourcePage":350},{"id":"apush-period-4-c7","front":"Amistad (1839)","back":"Spanish slave ship dramatically seized off the coast of Cuba by the enslaved Africans aboard. The ship was driven ashore in Long Island and the slaves were put on trial. Former president John Quincy Adams argued their case before the Supreme Court, securing their eventual release.","sourcePage":384},{"id":"apush-period-4-c8","front":"Bank War (1832)","back":"Battle between President Andrew Jackson and Congressional supporters of the Bank of the United States over the bank’s renewal in 1832. Jackson vetoed the Bank Bill, arguing that the bank favored moneyed interests at the expense of western farmers.","sourcePage":286},{"id":"apush-period-4-c9","front":"Black Hawk War (1832)","back":"Series of clashes in Illinois and Wisconsin between American forces and Indian chief Black Hawk of the Sauk and Fox tribes, who unsuccessfully tried to reclaim territory lost under the 1830 Indian Removal Act.","sourcePage":285},{"id":"apush-period-4-c10","front":"Brook Farm (1841–1846)","back":"Transcendentalist commune founded by a group of intellectuals, who emphasized living plainly while pursuing the life of the mind. The community fell into debt and dissolved when their communal home burned to the ground in 1846.","sourcePage":354},{"id":"apush-period-4-c11","front":"Burned-Over District","back":"Popular name for Western New York, a region particularly swept up in the religious fervor of the Second Great Awakening.","sourcePage":343},{"id":"apush-period-4-c12","front":"Chesapeake affair (1807)","back":"Conflict between Britain and the United States that precipitated the 1807 embargo. The conflict developed when a British ship, in search of deserters, fired on the American Chesapeake off the coast of Virginia.","sourcePage":239},{"id":"apush-period-4-c13","front":"Cohens v. Virginia (1821)","back":"Case that reinforced federal supremacy by establishing the right of the Supreme Court to review decisions of state supreme courts in questions involving the powers of the federal government.","sourcePage":263},{"id":"apush-period-4-c14","front":"Commonwealth v. Hunt (1842)","back":"Mas sa chu setts Supreme Court decision that strengthened the labor movement by upholding the legality of unions.","sourcePage":324},{"id":"apush-period-4-c15","front":"compromise Tariff of 1833","back":"Passed as a measure to resolve the nullification crisis, it provided that tariffs be lowered gradually, over a period of ten years, to 1816 levels.","sourcePage":282},{"id":"apush-period-4-c16","front":"Corps of Discovery (1804–1806)","back":"Team of adventurers, led by Meriwether Lewis and William Clark, sent by T homas Jefferson to explore Louisiana Territory and find a water route to the Pacific. Louis and Clark brought back detailed accounts of the West’s flora, fauna and native populations, and their voyage demonstrated the viability of overland travel to the west.","sourcePage":236},{"id":"apush-period-4-c17","front":"corrupt bargain","back":"Alleged deal between presidential candidates John Quincy Adams and Henry Clay to throw the election, to be decided by the House of Representatives, in Adams’ favor. Though never proven, the accusation became the rallying cry for supporters of Andrew Jackson, who had actually garnered a plurality of the popular vote in 1824.","sourcePage":273},{"id":"apush-period-4-c18","front":"cult of domesticity","back":"Pervasive nineteenth century cultural creed that venerated the domestic role of women. It gave married women greater authority to shape home life but limited opportunities outside the domestic sphere.","sourcePage":325},{"id":"apush-period-4-c19","front":"Dartmouth College v. Woodward (1819)","back":"Supreme Court case that sustained Dartmouth University’s original charter against changes proposed by the New Hampshire state legislature, thereby protecting corporations from domination by state governments.","sourcePage":264},{"id":"apush-period-4-c20","front":"deism","back":"Eighteenth century religious doctrine that emphasized reasoned moral behavior and the scientific pursuit of knowledge. Most deists rejected biblical inerrancy and the divinity of Christ, but they did believe that a Supreme Being created the universe.","sourcePage":341},{"id":"apush-period-4-c21","front":"ecological imperialism","back":"Historians’ term for the spoliation of Western natural resources through excessive hunting, logging, mining, and grazing.","sourcePage":307},{"id":"apush-period-4-c22","front":"Embargo Act (1807)","back":"Enacted in response to British and French mistreatment of American merchants, the Act banned the export all goods from the United States to any foreign port. The embargo placed great strains on the American economy while only marginally affecting its European targets, and was therefore repealed in 1809.","sourcePage":240},{"id":"apush-period-4-c23","front":"Era of Good Feelings (1816–1824)","back":"Popular name for the period of one-party, Republican, rule during James Monroe’s presidency. The term obscures bitter conflicts over internal improvements, slavery, and the national bank.","sourcePage":258},{"id":"apush-period-4-c24","front":"Erie Canal (completed 1825)","back":"New York state canal that linked Lake Erie to the Hudson River. It dramatically lowered shipping costs, fueling an economic boom in upstate New York and increasing the profitability of farming in the Old Northwest.","sourcePage":329},{"id":"apush-period-4-c25","front":"Florida Purchase Treaty (Adams-Onís Treaty) (1819)","back":"Under the agreement, Spain ceded Florida to the United States, which, in exchange, abandoned its claims to Texas.","sourcePage":267},{"id":"apush-period-4-c26","front":"Force Bill (1833)","back":"Passed by Congress alongside the Compromise Tariff, it authorized the president to use the military to collect federal tariff duties.","sourcePage":283},{"id":"apush-period-4-c27","front":"Gag Resolution","back":"Prohibited debate or action on antislav ery appeals. Driven through the House by pro-slavery Southerners, the gag resolution passed e very year for eight years, eventually overturned with the help of John Quincy Adams.","sourcePage":391},{"id":"apush-period-4-c28","front":"Ghent, Treaty of (1815)","back":"Ended the War of 1812 in a virtual draw, restoring prewar borders but failing to address any of the grievances that first brought America into the war.","sourcePage":252},{"id":"apush-period-4-c29","front":"Gibbons v. Ogden (1824)","back":"Suit over whether New York State could grant a monopoly to a ferry operating on interstate waters. The ruling reasserted that Congress had the sole power to regulate interstate commerce.","sourcePage":263},{"id":"apush-period-4-c30","front":"Hartford Convention (1814–1815)","back":"Convention of Federalists from five New England states who opposed the War of 1812 and resented the strength of Southern and Western interests in Congress and the White House.","sourcePage":253},{"id":"apush-period-4-c31","front":"Hudson River school (mid-nineteenth century)","back":"American artistic movement that produced romantic renditions of local landscapes.","sourcePage":359},{"id":"apush-period-4-c32","front":"Indian Removal Act (1830)","back":"Ordered the removal of Indian Tribes still residing east of the Mississippi to newly established Indian Territory west of Arkansas and Missouri. Tribes resisting eviction were forcibly removed by American forces, often after prolonged legal or military battles.","sourcePage":285},{"id":"apush-period-4-c33","front":"Know-Nothing party (1850s)","back":"Nativist political party, also known as the American party, which emerged in response to an influx of immigrants, particularly Irish Catholics.","sourcePage":314},{"id":"apush-period-4-c34","front":"The Liberator (1831–1865)","back":"Antislav ery newspaper published by William Lloyd Garrison, who called for the immediate emancipation of all slaves.","sourcePage":386},{"id":"apush-period-4-c35","front":"limited liability","back":"Legal principle that facilitates capital investment by offering protection for individual investors, who, in cases of legal claims or bankruptcy, cannot be held responsible for more than the value of their individual shares.","sourcePage":321},{"id":"apush-period-4-c36","front":"Louisiana Purchase (1803)","back":"Acquisition of Louisiana territory from France. The purchase more than doubled the territory of the United States, opening vast tracts for settlement.","sourcePage":236},{"id":"apush-period-4-c37","front":"Marbury v. Madison (1803)","back":"Supreme Court case that established the principle of “judicial review”—the idea that the Supreme Court had the final authority to determine constitutionality.","sourcePage":232},{"id":"apush-period-4-c38","front":"market revolution","back":"Eighteenth- and nineteenth-century transformation from a disaggregated, subsistence economy to a national commercial and industrial network.","sourcePage":335},{"id":"apush-period-4-c39","front":"McCormick reaper (1831)","back":"Mechanized the harvest of grains, such as wheat, allowing farmers to cultivate larger plots. The introduction of the reaper in the 1830s fueled the establishment of largescale commercial agriculture in the Midwest.","sourcePage":328},{"id":"apush-period-4-c40","front":"McCulloch v. Maryland (1819)","back":"Supreme Court case that strengthened federal authority and upheld the constitutionality of the Bank of the United States by establishing that the State of Maryland did not have power to tax the bank.","sourcePage":263},{"id":"apush-period-4-c41","front":"Missouri Compromise (1820)","back":"Allowed Missouri to enter as a slave state but preserved the balance between North and South by carving free-soil Maine out of Mas sa chu setts and prohibiting slav ery from territories acquired in the Louisiana Purchase, north of the line of 36°30'.","sourcePage":263},{"id":"apush-period-4-c42","front":"Monroe Doctrine (1823)","back":"Statement delivered by President James Monroe, warning European powers to refrain from seeking any new territories in the Americas. The United States largely lacked the power to back up the pronouncement, which was actually enforced by the British, who sought unfettered access to Latin American markets.","sourcePage":268},{"id":"apush-period-4-c43","front":"Mormons","back":"Religious followers of Joseph Smith, who founded a communal, oligarchic religious order in the 1830s, officially known as the Church of Jesus Christ of Latter-Day Saints. Mormons, facing deep hostility from their non-Mormon neighbors, eventually migrated west and established a flourishing settlement in the Utah desert.","sourcePage":343},{"id":"apush-period-4-c44","front":"Nat Turner’s rebellion (1831)","back":"Virginia slave revolt that resulted in the deaths of sixty whites and raised fears among white Southerners of further uprisings.","sourcePage":384},{"id":"apush-period-4-c45","front":"New Orleans, Battle of (January 1815)","back":"Resounding victory of American forces against the British, restoring American confidence and fueling an outpouring of nationalism. Final battle of the War of 1812.","sourcePage":252},{"id":"apush-period-4-c46","front":"Non-Intercourse Act (1809)","back":"Passed alongside the repeal of the Embargo Act, it reopened trade with all but the two belligerent nations, Britain and France. The Act continued Jefferson’s policy of economic coercion, still with little effect.","sourcePage":242},{"id":"apush-period-4-c47","front":"Nullification Crisis (1832–1833)","back":"Showdown between President Andrew Jackson and the South Carolina legislature, which declared the 1832 tariff null and void in the state and threatened secession if the federal government tried to collect duties. It was resolved by a compromise negotiated by Henry Clay in 1833.","sourcePage":282},{"id":"apush-period-4-c48","front":"panic of 1819","back":"Severe financial crisis brought on primarily by the efforts of the Bank of the United States to curb overspeculation on western lands. It disproportionately affected the poorer classes, especially in the West, sowing the seeds of Jacksonian Democracy.","sourcePage":258},{"id":"apush-period-4-c49","front":"panic of 1837","back":"Economic crisis triggered by bank failures, elevated grain prices, and Andrew Jackson’s efforts to curb overspeculation on western lands and transportation improvements. In response, President Martin Van Buren proposed the “Divorce Bill,” which pulled treasury funds out of the banking system altogether, contracting the credit supply.","sourcePage":292},{"id":"apush-period-4-c50","front":"patronage","back":"Practice of rewarding political support with special favors, often in the form of public office. Upon assuming office, Thomas Jefferson dismissed few Federalist employees, leaving scant openings to fill with political appointees.","sourcePage":230},{"id":"apush-period-4-c51","front":"peculiar institution","back":"Widely used term for the institution of American slav ery in the South. Its use in the first half of the 19th century reflected a growing division between the North, where slavery was gradually abolished, and the South, where slav ery became increasingly entrenched.","sourcePage":262},{"id":"apush-period-4-c52","front":"pet banks","back":"Popular term for pro-Jackson state banks that received the bulk of federal deposits when Andrew Jackson moved to dismantle the Bank of the United States in 1833.","sourcePage":290},{"id":"apush-period-4-c53","front":"Revolution of 1800","back":"Electoral victory of Democratic Republicans over the Federalists, who lost their Congressional majority and the presidency. The peaceful transfer of power between rival parties solidified faith in America’s political system.","sourcePage":226},{"id":"apush-period-4-c54","front":"Rush-Bagot agreement (1817)","back":"Signed by Britain and the United States, it established strict limits on naval armaments in the Great Lakes, a first step in the full demilitarization of the U.S.-Canadian border, completed in the 1870s.","sourcePage":255},{"id":"apush-period-4-c55","front":"San Jacinto, Battle of (1836)","back":"Resulted in the capture of Mexican dictator Santa Anna, who was forced to withdraw his troops from Texas and recognize the Rio Grande as Texas’s Southwestern border.","sourcePage":295},{"id":"apush-period-4-c56","front":"Second Great Awakening (early nineteenth century)","back":"Religious revival characterized by emotional mass “camp meetings” and widespread conversion. Brought about a demo cratization of religion as a multiplicity of denominations vied for members.","sourcePage":341},{"id":"apush-period-4-c57","front":"“Self-Reliance” (1841)","back":"Ralph Waldo Emerson’s popular lectureessay that reflected the spirit of individualism pervasive in American popular culture during the 1830s and 1840s.","sourcePage":306},{"id":"apush-period-4-c58","front":"Specie Circular (1836)","back":"U.S. Treasury decree requiring that all public lands be purchased with “hard,” or metallic, currency. Issued after small state banks flooded the market with unreliable paper currency, fueling land speculation in the West.","sourcePage":290},{"id":"apush-period-4-c59","front":"spoils system","back":"Policy of rewarding political supporters with public office, first widely employed at the federal level by Andrew Jackson. The practice was widely abused by unscrupulous office seekers, but it also helped cement party loyalty in the emerging two-party system.","sourcePage":280},{"id":"apush-period-4-c60","front":"Tallmadge amendment (1819)","back":"Failed proposal to prohibit the importation of slaves into Missouri territory and pave the way for gradual emancipation. Southerners vehemently opposed the amendment, which they perceived as a threat to the sectional balance between North and South.","sourcePage":259},{"id":"apush-period-4-c61","front":"Tariff of Abominations (1828)","back":"Noteworthy for its unprecedentedly high duties on imports. Southerners vehemently opposed the Tariff, arguing that it hurt Southern farmers, who did not enjoy the protection of tariffs, but were forced to pay higher prices for manufactures.","sourcePage":280},{"id":"apush-period-4-c62","front":"Tippecanoe, Battle of (1811)","back":"Resulted in the defeat of Shawnee chief Tenskwatawa, “the Prophet” at the hands William Henry Harrison in the Indiana wilderness. After the battle, the Prophet’s brother, Tecumseh, forged an alliance with the British against the United States.","sourcePage":245},{"id":"apush-period-4-c63","front":"Trail of Tears (1838–1839)","back":"Forced march of 15,000 Cherokee Indians from their Georgia and Alabama homes to Indian Territory. Some 4,000 Cherokee died on the arduous journey.","sourcePage":285},{"id":"apush-period-4-c64","front":"transcendentalism (mid-nineteenth century)","back":"Literary and intellectual movement that emphasized individualism and self-reliance, predicated upon a belief that each person possesses an “innerlight” that can point the way to truth and direct contact with God.","sourcePage":361},{"id":"apush-period-4-c65","front":"transportation revolution","back":"Term referring to a series of nineteenthcentury transportation innovations—turnpikes, steamboats, canals, and railroads—that linked local and regional markets, creating a national economy.","sourcePage":334},{"id":"apush-period-4-c66","front":"Tripolitan War (1801–1805)","back":"Four-year conflict between the American Navy and the North-African nation of Tripoli over piracy in the Mediterranean. Jefferson, a staunch noninterventionist, reluctantly deployed American forces, eventually securing a peace treaty with Tripoli.","sourcePage":234},{"id":"apush-period-4-c67","front":"turnpike","back":"Privately funded, toll-based public road constructed in the early nineteenth century to facilitate commerce.","sourcePage":328},{"id":"apush-period-4-c68","front":"Unitarians","back":"Believe in a unitary deity, reject the divinity of Christ, and emphasize the inherent goodness of mankind. Unitarianism, inspired in part by Deism, first caught on in New England at the end of the eighteenth century.","sourcePage":341},{"id":"apush-period-4-c69","front":"war hawks (1811–1812)","back":"Democratic-Republican Congressmen who pressed James Madison to declare war on Britain. Largely drawn from the South and West, the war hawks resented British constraints on American trade and accused the British of supporting Indian attacks against American settlements on the frontier.","sourcePage":244},{"id":"apush-period-4-c70","front":"War of 1812 (1812–1815)","back":"Fought between Britain and the United States largely over the issues of trade and impressment. Though the war ended in a relative draw, it demonstrated America’s willingness to defend its interests militarily, earning the young nation newfound respect from European powers.","sourcePage":248}],"questions":[],"feynmanPrompts":[{"id":"apush-period-4-f1","prompt":"Democratization and the market revolution"},{"id":"apush-period-4-f2","prompt":"Expansion, migration, and Native displacement"},{"id":"apush-period-4-f3","prompt":"Religious revival and reform movements"},{"id":"apush-period-4-f4","prompt":"National identity and growing sectionalism"},{"id":"apush-period-4-f5","prompt":"The Market Revolution"},{"id":"apush-period-4-f6","prompt":"Jacksonian democracy"},{"id":"apush-period-4-f7","prompt":"The Second Great Awakening"}]},{"id":"apush-period-5","name":"AP U.S. History · Period 5: 1844–1877","shortName":"Period 5: 1844–1877","builtIn":true,"sourceTitle":"Glossary of Key Terms — The American Pageant","sourceUrl":"https://loscosapush.weebly.com/uploads/5/2/4/8/52484185/glossary_of_key_terms_-_american_pageant.pdf","cards":[{"id":"apush-period-5-c1","front":"“10 percent” Reconstruction plan (1863)","back":"Introduced by President Lincoln, it proposed that a state be readmitted to the Union once 10 percent of its voters had pledged loyalty to the United States and promised to honor emancipation.","sourcePage":519},{"id":"apush-period-5-c2","front":"Antietam, Battle of (September 1862)","back":"Landmark battle in the Civil War that essentially ended in a draw but demonstrated the prowess of the Union army, forestalling foreign intervention and giving Lincoln the “victory” he needed to issue the Emancipation Proclamation.","sourcePage":487},{"id":"apush-period-5-c3","front":"Appomattox Courthouse","back":"Site where Robert E. Lee surrendered to Ulysses S. Grant in April 1865 after almost a year of brutal fighting throughout Virginia in the “Wilderness Campaign.”","sourcePage":503},{"id":"apush-period-5-c4","front":"Black Codes (1865–1866)","back":"Laws passed throughout the South to restrict the rights of emancipated blacks, particularly with respect to negotiating labor contracts. Increased Northerners’ criticisms of President Andrew Johnson’s lenient Reconstruction policies.","sourcePage":521},{"id":"apush-period-5-c5","front":"Bleeding Kansas (1856–1861)","back":"Civil war in Kansas over the issue of slav ery in the territory, fought intermittently until 1861, when it merged with the wider national Civil War.","sourcePage":442},{"id":"apush-period-5-c6","front":"Border States","back":"Five slave states-Missouri, Kentucky, Maryland, Delaware and West Virginia—that did not secede during the Civil War. To keep the states in the Union, Abraham Lincoln insisted that the war was not about abolishing slavery but rather protecting the Union.","sourcePage":463},{"id":"apush-period-5-c7","front":"Bull Run (Manassas Junction), Battle of (July 1861)","back":"First major battle of the Civil War and a victory for the South, it dispelled Northern illusions of swift victory.","sourcePage":481},{"id":"apush-period-5-c8","front":"California gold rush (beginning in 1849)","back":"Inflow of thousands of miners to Northern Cal i fornia after news reports of the discovery of gold at Sutter’s Mill in January of 1848 had spread around the world by the end of that year. The onslaught of migrants prompted Cal i fornians to organize a government and apply for statehood in 1849.","sourcePage":419},{"id":"apush-period-5-c9","front":"carpetbaggers","back":"Pejorative used by Southern whites to describe Northern businessmen and politicians who came to the South after the Civil War to work on Reconstruction projects or invest in Southern infrastructure.","sourcePage":528},{"id":"apush-period-5-c10","front":"Civil Rights Bill (1866)","back":"Passed over Andrew Johnson’s veto, the bill aimed to counteract the Black Codes by conferring citizenship on African Americans and making it a crime to deprive blacks of their rights to sue, testify in court, or hold property.","sourcePage":522},{"id":"apush-period-5-c11","front":"Compromise of 1850","back":"Admitted Cal i fornia as a free state, opened New Mexico and Utah to popular sovereignty, ended the slave trade (but not slav ery itself) in Washington D.C., and introduced a more stringent fugitive slave law. Widely opposed in both the North and South, it did little to settle the escalating dispute over slav ery.","sourcePage":423},{"id":"apush-period-5-c12","front":"Confederate States of America (1861–1865)","back":"Government established after seven Southern states seceded from the Union. Later joined by four more states from the Upper South.","sourcePage":455},{"id":"apush-period-5-c13","front":"Constitutional Union party (1860)","back":"Formed by moderate Whigs and Know-Nothings in an effort to elect a compromise candidate and avert a sectional crisis.","sourcePage":452},{"id":"apush-period-5-c14","front":"Copperheads","back":"Northern Democrats who obstructed the war effort attacking Abraham Lincoln, the draft and, after 1863, emancipation.","sourcePage":499},{"id":"apush-period-5-c15","front":"Crittenden amendments (1860)","back":"Proposed in an attempt to appease the South, the failed Constitutional amendments would have given federal protection for slav ery in all territories south of 36°30’ where slav ery was supported by popular sovereignty.","sourcePage":456},{"id":"apush-period-5-c16","front":"Dred Scott v. Sandford (1857)","back":"Supreme Court decision that extended federal protection to slavery by ruling that Congress did not have the power to prohibit slav ery in any territory. Also declared that slaves, as property, were not citizens of the United States.","sourcePage":445},{"id":"apush-period-5-c17","front":"Emancipation Proclamation (1863)","back":"Declared all slaves in rebelling states to be free but did not affect slav ery in non-rebelling Border States. The Proclamation closed the door on possible compromise with the South and encouraged thousands of Southern slaves to to Union lines.","sourcePage":487},{"id":"apush-period-5-c18","front":"Ex parte Milligan (1866)","back":"Civil War Era case in which the Supreme Court ruled that military tribunals c ould not be used to try civilians if civil courts were open.","sourcePage":526},{"id":"apush-period-5-c19","front":"Fifteenth Amendment (ratified 1870)","back":"Prohibited states from denying citizens the franchise on account of race. It disappointed feminists who wanted the Amendment to include guarantees for womof en’s suffrage.","sourcePage":526},{"id":"apush-period-5-c20","front":"“Fifty-four forty or fight” (1846)","back":"Slogan adopted by midnineteenth century expansionists who advocated the occupation of Oregon territory, jointly held by Britain and the United States. Though President Polk had pledged to seize all of Oregon, to 54° 40', he settled on the forty-ninth parallel as a compromise with the British.","sourcePage":403},{"id":"apush-period-5-c21","front":"Force Acts (1870–1871)","back":"Passed by Congress following a wave of Ku Klux Klan violence, the acts banned clan membership, prohibited the use of intimidation to prevent blacks from voting, and gave the U.S. military the authority to enforce the acts.","sourcePage":530},{"id":"apush-period-5-c22","front":"Fort Sumter","back":"South Carolina location where Confederate forces fired the first shots of the Civil War in April of 1861, after Union forces attempted to provision the fort.","sourcePage":463},{"id":"apush-period-5-c23","front":"Fourteenth Amendment (ratified 1868)","back":"Constitutional amendment that extended civil rights to freedmen and prohibited States from taking away such rights without due process.","sourcePage":523},{"id":"apush-period-5-c24","front":"Free Soil party (1848–1854)","back":"Antislav ery party in the 1848 and 1852 elections that opposed the extension of slav ery into the territories, arguing that the presence of slav ery would limit opportunities for free laborers.","sourcePage":417},{"id":"apush-period-5-c25","front":"Freedmen’s Bureau (1865–1872)","back":"Created to aid newly emancipated slaves by providing food, clothing, medical care, education and legal support. Its achievements were uneven and depended largely on the quality of local administrators.","sourcePage":518},{"id":"apush-period-5-c26","front":"Freeport Doctrine (1858)","back":"Declared that since slav ery could not exist without laws to protect it, territorial legislatures, not the Supreme Court, would have the final say on the slav ery question. First argued by Stephen Douglass in 1858 in response to Abraham Lincoln’s “Freeport Question”.","sourcePage":449},{"id":"apush-period-5-c27","front":"Fugitive Slave Law (1850)","back":"Passed as part of the Compromise of 1850, it set high penalties for anyone who aided escaped slaves and compelled all law enforcement officers to participate in retrieving runaways. Strengthened the antislavery cause in the North.","sourcePage":425},{"id":"apush-period-5-c28","front":"Gadsden Purchase (1853)","back":"Acquired additional land from Mexico for $10 million to facilitate the construction of a southern transcontinental railroad.","sourcePage":432},{"id":"apush-period-5-c29","front":"Gettysburg Address (1863)","back":"Abraham Lincoln’s oft-quoted speech, delivered at the dedication of the cemetery at Gettysburg battlefield. In the address, Lincoln framed the war as a means to uphold the values of liberty.","sourcePage":494},{"id":"apush-period-5-c30","front":"Gettysburg, Battle of (July 1863)","back":"Civil War battle in Pennsylvania that ended in Union victory, spelling doom for the Confederacy, which never again managed to invade the North. Site of General George Pickett’s daring but doomed charge on the Northern lines.","sourcePage":492},{"id":"apush-period-5-c31","front":"greenbacks","back":"Paper currency issued by the Union Treasury during the Civil War. Inadequately supported by gold, Greenbacks fluctuated in value throughout the war, reaching a low of 39 cents on the dollar.","sourcePage":477},{"id":"apush-period-5-c32","front":"Guadalupe Hidalgo, Treaty of (1848)","back":"Ended the war with Mexico. Mexico agreed to cede territory reaching northwest from Texas to Oregon in exchange for $18.25 million in cash and assumed debts.","sourcePage":410},{"id":"apush-period-5-c33","front":"Harpers Ferry","back":"Federal arsenal in Virginia seized by abolitionist John Brown in 1859. Though Brown was later captured and executed, his raid alarmed Southerners who believed that Northerners shared in Brown’s extremism.","sourcePage":450},{"id":"apush-period-5-c34","front":"Homestead Act (1862)","back":"A federal law that gave settlers 160 acres of land for about $30 if they lived on it for five years and improved it by, for instance, building a house on it. The act helped make land accessible to hundreds of thousands of westward-moving settlers, but many people also found disappointment when their land was infertile or they saw speculators grabbing up the best land.","sourcePage":479},{"id":"apush-period-5-c35","front":"The Impending Crisis of the South (1857)","back":"Antislav ery tract, written by white Southerner Hinton R. Helper, arguing that nonslaveholding whites actually suffered most in a slave economy.","sourcePage":439},{"id":"apush-period-5-c36","front":"Kansas-Nebraska Act (1854)","back":"Proposed that the issue of slav ery be decided by popular sovereignty in the Kansas and Nebraska territories, thus revoking the 1820 Missouri Compromise. Introduced by Stephen Douglass in an effort to bring Nebraska into the Union and pave the way for a northern transcontinental railroad.","sourcePage":434},{"id":"apush-period-5-c37","front":"Ku Klux Klan","back":"An extremist, paramilitary, right-wing secret society founded in the mid-nineteenth century and revived during the 1920s. It was anti-foreign, anti-black, anti-Jewish, anti-pacifist, anti-Communist, anti-internationalist, anti-evolutionist, and anti-bootlegger, but pro-Anglo-Saxon and pro-Protestant. Its members, cloaked in sheets to conceal their identities, terrorized freedmen and sympathetic whites throughout the South after the Civil War. By the 1890s, Klan-style violence and Democratic legislation succeeded in virtually disenfranchising all Southern blacks.","sourcePage":529},{"id":"apush-period-5-c38","front":"Lecompton Constitution (1857)","back":"Proposed Kansas constitution, whose ratification was unfairly rigged so as to guarantee slavery in the territory. Initially ratified by proslavery forces, it was later voted down when Congress required that the entire constitution be put up for a vote.","sourcePage":441},{"id":"apush-period-5-c39","front":"Lincoln-Douglas debates (1858)","back":"Series of debates between Abraham Lincoln and Stephen Douglass during the U.S. Senate race in Illinois. Douglass won the election but Lincoln gained national prominence and emerged as the leading candidate for the 1860 Republican nomination.","sourcePage":448},{"id":"apush-period-5-c40","front":"Manifest Destiny (1840s and 1850s)","back":"Belief that the United States was destined by God to spread its “empire of liberty” across North America. Served as a justification for mid-nineteenth century expansionism.","sourcePage":403},{"id":"apush-period-5-c41","front":"Narrative of the Life of Frederick Douglass (1845)","back":"Vivid autobiography of the escaped slave and renowned abolitionist Frederick Douglass.","sourcePage":387},{"id":"apush-period-5-c42","front":"National Banking System (1863)","back":"Network of member banks that could issue currency against purchased government bonds. Created during the Civil War to establish a stable national currency and stimulate the sale of war bonds.","sourcePage":477},{"id":"apush-period-5-c43","front":"New York draft riots (1863)","back":"Uprising, mostly of working-class IrishAmericans, in protest of the draft. Rioters were particularly incensed by the ability of the rich to hire substitutes or purchase exemptions.","sourcePage":475},{"id":"apush-period-5-c44","front":"Ostend Manifesto (1854)","back":"Secret Franklin Pierce administration proposal to purchase or, that failing, to wrest militarily Cuba from Spain. Once leaked, it was quickly abandoned due to vehement opposition from the North.","sourcePage":430},{"id":"apush-period-5-c45","front":"panic of 1857","back":"Financial crash brought on by gold-fueled inflation, overspeculation, and excess grain production. Raised calls in the North for higher tariffs and for free homesteads on western public lands.","sourcePage":446},{"id":"apush-period-5-c46","front":"popular sovereignty","back":"(in the context of the slav ery debate) Notion that the sovereign p eople of a given territory should decide whether to allow slav ery. Seemingly a compromise, it was largely opposed by Northern abolitionists who feared it would promote the spread of slav ery to the territories.","sourcePage":417},{"id":"apush-period-5-c47","front":"Reconstruction Act (1867)","back":"Passed by the newly-elected Republican Congress, it divided the South into five military districts, disenfranchised former confederates, and required that Southern states both ratify the Fourteenth Amendment and write state constitutions guaranteeing freedmen the franchise before gaining readmission to the Union.","sourcePage":525},{"id":"apush-period-5-c48","front":"Redeemers","back":"Southern Democratic politicians who sought to wrest control from Republican regimes in the South after Reconstruction.","sourcePage":527},{"id":"apush-period-5-c49","front":"Reform Bill of 1867","back":"Granted suffrage to all male British citizens, dramatically expanding the electorate. The success of the American dem o cratic experiment, reinforced by the Union victory in the Civil War, was used as one of the arguments in favor of the Bill.","sourcePage":509},{"id":"apush-period-5-c50","front":"scalawags","back":"Derogatory term for pro-Union Southerners whom Southern Democrats accused of plundering the resources of the South in collusion with Republican governments after the Civil War.","sourcePage":528},{"id":"apush-period-5-c51","front":"Seventh of March speech (1850)","back":"Daniel Webster’s impassioned address urging the North to support of the Compromise of 1850. Webster argued that topography and climate would keep slavery from becoming entrenched in Mexican Cession territory and urged Northerners to make all reasonable concessions to prevent disunion.","sourcePage":422},{"id":"apush-period-5-c52","front":"Seward’s Folly (1867)","back":"Popular term for Secretary of State William Seward’s purchase of Alaska from Russia. The derisive term reflected the anti-expansionist sentiments of most Americans immediately after the Civil War.","sourcePage":532},{"id":"apush-period-5-c53","front":"Sherman’s march (1864–1865)","back":"Union General William Tecumseh Sherman’s destructive march through Georgia. An early instance of “total war,” purposely targeting infrastructure and civilian property to diminish morale and undercut the Confederate war effort.","sourcePage":497},{"id":"apush-period-5-c54","front":"Shiloh, Battle of (April 1862)","back":"Bloody Civil War battle on the Tennessee-Mississippi border that resulted in the deaths of more than 23,000 soldiers and ended in a marginal Union victory.","sourcePage":495},{"id":"apush-period-5-c55","front":"Tenure of Office Act (1867)","back":"Required the President to seek approval from the Senate before removing appointees. When Andrew Johnson removed his secretary of war in violation of the act, he was impeached by the house but remained in office when the Senate fell one vote short of removing him.","sourcePage":531},{"id":"apush-period-5-c56","front":"Thirteenth Amendment (1865)","back":"Constitutional amendment prohibiting all forms of slav ery and involuntary servitude. Former Confederate States were required to ratify the amendment prior to gaining reentry into the Union.","sourcePage":489},{"id":"apush-period-5-c57","front":"Uncle Tom’s Cabin (1852)","back":"Harriet Beecher Stowe’s widely read novel that dramatized the horrors of slavery. It heightened Northern support for abolition and escalated the sectional conflict.","sourcePage":437},{"id":"apush-period-5-c58","front":"Underground Railroad","back":"Informal network of volunteers that helped runaway slaves escape from the South and reach free-soil Canada. Seeking to halt the flow of runaway slaves to the North, Southern planters and congressmen pushed for a stronger fugitive slave law.","sourcePage":420},{"id":"apush-period-5-c59","front":"Vicksburg, siege of (1863)","back":"Two-and-a-half-month siege of a Confederate fort on the Mississippi River in Tennessee. Vicksburg finally fell to Ulysses S. Grant in July of 1863, giving the Union Army control of the Mississippi River and splitting the South in two.","sourcePage":495},{"id":"apush-period-5-c60","front":"Wade-Davis Bill","back":"Passed by Congressional Republicans in response to Abraham Lincoln’s “10 percent plan,” it required that 50 percent of a state’s voters pledge allegiance to the Union, and set stronger safeguards for emancipation. Reflected divisions between Congress and the President, and between radical and moderate Republicans, over the treatment of the defeated South.","sourcePage":519},{"id":"apush-period-5-c61","front":"Wilmot Proviso (1846)","back":"Amendment that sought to prohibit slav ery from territories acquired from Mexico. Introduced by Pennsylvania congressman David Wilmot, the failed amendment ratcheted up tensions between North and South over the issue of slav ery.","sourcePage":414},{"id":"apush-period-5-c62","front":"Woman’s Rights Convention at Seneca Falls (1848)","back":"Gathering of feminist activists in Seneca Falls, New York, where Elizabeth Cady Stanton read her “Declaration of Sentiments,” stating that “all men and women are created equal.”","sourcePage":352},{"id":"apush-period-5-c63","front":"writ of habeas corpus","back":"Petition requiring law enforcement officers to present detained individuals before the court to examine the legality of the arrest. Protects individuals from arbitrary state action. Suspended by Lincoln during the Civil War.","sourcePage":475}],"questions":[],"feynmanPrompts":[{"id":"apush-period-5-f1","prompt":"Manifest Destiny and the Mexican-American War"},{"id":"apush-period-5-f2","prompt":"Slavery and the sectional crisis"},{"id":"apush-period-5-f3","prompt":"The Civil War"},{"id":"apush-period-5-f4","prompt":"Emancipation and Reconstruction"},{"id":"apush-period-5-f5","prompt":"Citizenship and constitutional change"},{"id":"apush-period-5-f6","prompt":"Causes of the Civil War"}]},{"id":"apush-period-6","name":"AP U.S. History · Period 6: 1865–1898","shortName":"Period 6: 1865–1898","builtIn":true,"sourceTitle":"AP US History Flashcards by Time Period — APUSHReview","sourceUrl":"https://www.apushreview.com/additional-resources/ap-us-history-flashcards-by-time-period/","cards":[{"id":"apush-period-6-c1","front":"Gilded Age","back":"The period from the 1870s through the 1890s when rapid industrial growth and displays of prosperity concealed political corruption, labor conflict, inequality, and poverty.","sourcePage":"Period 6"},{"id":"apush-period-6-c2","front":"Social Darwinism","back":"The application of ideas about natural selection to human society, often used by industrialists and their defenders to portray wealth and poverty as the results of competition and individual fitness.","sourcePage":"Period 6"},{"id":"apush-period-6-c3","front":"Labor unions in the Gilded Age","back":"Organizations such as the Knights of Labor and the American Federation of Labor that sought higher wages, shorter hours, safer workplaces, and greater bargaining power for workers.","sourcePage":"Period 6"},{"id":"apush-period-6-c4","front":"New South","back":"The post–Civil War vision of a more industrial and economically diversified South, although agriculture, racial inequality, sharecropping, and tenant farming remained dominant.","sourcePage":"Period 6"},{"id":"apush-period-6-c5","front":"Sharecropping","back":"A labor system in which farmers worked land owned by someone else and paid the owner with a share of the crop, frequently trapping Black and poor white families in cycles of debt.","sourcePage":"Period 6"},{"id":"apush-period-6-c6","front":"Mechanized agriculture","back":"The growing use of machinery to increase farm output, which encouraged commercial agriculture but also displaced workers and contributed to farmers’ debt and political organizing.","sourcePage":"Period 6"},{"id":"apush-period-6-c7","front":"People’s Party (Populist Party)","back":"A political movement formed largely by farmers and laborers that demanded railroad regulation, monetary reform, a graduated income tax, direct election of senators, and greater government responsiveness.","sourcePage":"Period 6"},{"id":"apush-period-6-c8","front":"Political machines","back":"Urban party organizations that exchanged jobs and services for votes and loyalty; they helped many immigrants navigate city life but were frequently associated with patronage and corruption.","sourcePage":"Period 6"},{"id":"apush-period-6-c9","front":"Settlement houses","back":"Community centers such as Jane Addams’s Hull House that offered education, childcare, health assistance, and other services to immigrants and working-class urban residents.","sourcePage":"Period 6"},{"id":"apush-period-6-c10","front":"Destruction of the buffalo herds","back":"The near extermination of bison through commercial hunting, railroad expansion, and federal policy, which undermined the economies and independence of many Plains Indigenous nations.","sourcePage":"Period 6"},{"id":"apush-period-6-c11","front":"Plessy v. Ferguson","back":"The 1896 Supreme Court decision that upheld racial segregation under the doctrine of “separate but equal,” giving constitutional protection to Jim Crow laws until Brown v. Board of Education.","sourcePage":"Period 6"},{"id":"apush-period-6-c12","front":"Assimilation of Native Americans","back":"Federal efforts to dissolve tribal identities and landholding through policies such as the Dawes Act and boarding schools that imposed private property, English, Christianity, and Euro-American customs.","sourcePage":"Period 6"},{"id":"apush-period-6-c13","front":"Social Gospel","back":"A Protestant reform movement that applied Christian ethics to problems created by industrialization, including poverty, poor housing, unsafe labor, and unequal urban conditions.","sourcePage":"Period 6"},{"id":"apush-period-6-c14","front":"Transcontinental Railroad","back":"The rail line completed in 1869 that connected eastern networks with the Pacific Coast, accelerating migration, trade, corporate growth, and Indigenous dispossession.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c15","front":"Homestead Act","back":"The 1862 law granting western land to settlers who lived on and improved it, encouraging migration while transferring Indigenous homelands to private ownership.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c16","front":"Pacific Railway Acts","back":"Federal laws that supported railroad construction with land grants and loans, enabling private corporations to build transcontinental lines.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c17","front":"Chinese Exclusion Act","back":"The 1882 federal law suspending immigration of Chinese laborers and barring Chinese immigrants from naturalization.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c18","front":"Dawes Act","back":"The 1887 law dividing tribal lands into individual allotments to promote assimilation, causing Indigenous nations to lose millions of acres.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c19","front":"Ghost Dance","back":"A Native religious movement promising cultural renewal and the restoration of Indigenous life that alarmed federal officials before the Wounded Knee massacre.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c20","front":"Wounded Knee Massacre","back":"The 1890 killing of hundreds of Lakota people by U.S. soldiers in South Dakota, marking the violent suppression of armed Indigenous resistance on the Plains.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c21","front":"Sand Creek Massacre","back":"The 1864 attack by Colorado militia on a peaceful Cheyenne and Arapaho encampment, killing many women and children.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c22","front":"Battle of Little Bighorn","back":"The 1876 victory of Lakota, Northern Cheyenne, and Arapaho forces over George Custer’s command, followed by intensified federal warfare.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c23","front":"Vertical integration","back":"A business strategy in which a company controls multiple stages of production and distribution, associated with Andrew Carnegie’s steel operations.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c24","front":"Horizontal integration","back":"A business strategy in which a company absorbs or eliminates competitors in the same industry, associated with John D. Rockefeller’s Standard Oil.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c25","front":"Trust","back":"A legal arrangement placing several companies under centralized control, used by large corporations to limit competition and dominate markets.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c26","front":"Monopoly","back":"Control of a market by one company or coordinated group, allowing it to influence prices, production, and competition.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c27","front":"Andrew Carnegie","back":"Steel industrialist who used vertical integration, promoted the Gospel of Wealth, and funded libraries and educational institutions.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c28","front":"John D. Rockefeller","back":"Founder of Standard Oil who used horizontal integration, rebates, and trusts to dominate petroleum refining.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c29","front":"J. P. Morgan","back":"Financier who consolidated corporations and reorganized industries, including the creation of U.S. Steel.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c30","front":"Gospel of Wealth","back":"Carnegie’s argument that the rich had a duty to use their fortunes for socially beneficial philanthropy.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c31","front":"Sherman Antitrust Act","back":"The 1890 law prohibiting combinations that restrained interstate trade, initially enforced weakly and sometimes used against labor unions.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c32","front":"Interstate Commerce Act","back":"The 1887 law regulating railroads and creating the Interstate Commerce Commission, the first federal regulatory agency.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c33","front":"Knights of Labor","back":"An inclusive national labor organization seeking broad economic reform and worker cooperation, weakened after association with the Haymarket affair.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c34","front":"American Federation of Labor","back":"A federation led by Samuel Gompers that organized skilled workers around wages, hours, and working conditions.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c35","front":"Haymarket affair","back":"The 1886 labor rally in Chicago where a bomb and police gunfire caused deaths, damaging the labor movement through association with radicalism.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c36","front":"Homestead Strike","back":"The violent 1892 steel strike at Carnegie’s Homestead plant that ended in defeat for the union.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c37","front":"Pullman Strike","back":"The 1894 railroad strike suppressed by federal troops after the government obtained an injunction and claimed interference with the mail.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c38","front":"Grange","back":"A farmers’ organization that promoted cooperation and regulation of railroad and grain-storage rates.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c39","front":"Interstate migration","back":"Movement within the United States toward cities, industrial centers, mining regions, and western farms in response to economic change.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c40","front":"New immigration","back":"Late nineteenth-century immigration increasingly originating in southern and eastern Europe and fueling nativist responses.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c41","front":"Tenements","back":"Crowded, poorly ventilated urban apartment buildings that housed many working-class and immigrant families.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c42","front":"Pendleton Civil Service Act","back":"The 1883 law establishing merit-based federal hiring for selected positions after criticism of the patronage system.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c43","front":"Mugwumps","back":"Republican reformers who opposed party corruption and supported Democrat Grover Cleveland in the 1884 election.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c44","front":"Jim Crow laws","back":"State and local measures enforcing racial segregation and Black political subordination after Reconstruction.","sourcePage":"CED Period 6"},{"id":"apush-period-6-c45","front":"Disenfranchisement","back":"The restriction of voting through poll taxes, literacy tests, intimidation, and other devices aimed especially at Black citizens.","sourcePage":"CED Period 6"}],"questions":[],"feynmanPrompts":[{"id":"apush-period-6-f1","prompt":"The Gilded Age"},{"id":"apush-period-6-f2","prompt":"Industrial capitalism and corporate consolidation"},{"id":"apush-period-6-f3","prompt":"Labor conflict in the Gilded Age"},{"id":"apush-period-6-f4","prompt":"Western settlement and Native dispossession"},{"id":"apush-period-6-f5","prompt":"Populism and farmer protest"}]},{"id":"apush-period-7","name":"AP U.S. History · Period 7: 1890–1945","shortName":"Period 7: 1890–1945","builtIn":true,"sourceTitle":"AP US History Flashcards by Time Period — APUSHReview","sourceUrl":"https://www.apushreview.com/additional-resources/ap-us-history-flashcards-by-time-period/","cards":[{"id":"apush-period-7-c1","front":"Closing of the frontier","back":"The 1890 Census Bureau announcement that a continuous western frontier line no longer existed, prompting Frederick Jackson Turner to argue that the frontier had shaped American democracy and identity.","sourcePage":"Period 7"},{"id":"apush-period-7-c2","front":"Progressive Era","back":"A reform period from roughly the 1890s through the 1920s in which activists used investigation, organization, and government action to address corruption, corporate power, unsafe conditions, and social inequality.","sourcePage":"Period 7"},{"id":"apush-period-7-c3","front":"Urbanization in the early twentieth century","back":"The shift of population and economic activity toward cities as industrial employment, immigration, and internal migration expanded; by 1920 a majority of Americans lived in urban places.","sourcePage":"Period 7"},{"id":"apush-period-7-c4","front":"Harlem Renaissance","back":"The flowering of African American literature, music, art, and intellectual life centered in 1920s Harlem, associated with figures including Langston Hughes, Zora Neale Hurston, and Duke Ellington.","sourcePage":"Period 7"},{"id":"apush-period-7-c5","front":"United States entry into World War I","back":"The 1917 decision to enter the war against Germany after unrestricted submarine warfare, the Zimmermann Telegram, economic ties to the Allies, and claims about defending democracy.","sourcePage":"Period 7"},{"id":"apush-period-7-c6","front":"Treaty of Versailles and League of Nations","back":"The post–World War I settlement and international organization championed by Woodrow Wilson; Senate opposition to collective-security commitments kept the United States out of the League.","sourcePage":"Period 7"},{"id":"apush-period-7-c7","front":"Great Migration","back":"The movement of millions of African Americans from the rural South to northern, midwestern, and western cities for industrial employment and relief from Jim Crow oppression.","sourcePage":"Period 7"},{"id":"apush-period-7-c8","front":"First Red Scare","back":"The post–World War I fear of communism, anarchism, and radical labor that contributed to the Palmer Raids, deportations, restrictions on dissent, and intensified nativism.","sourcePage":"Period 7"},{"id":"apush-period-7-c9","front":"Immigration quotas of the 1920s","back":"Federal laws that sharply limited immigration and used national-origins quotas favoring northern and western Europe while restricting southern and eastern Europeans and excluding most Asian immigrants.","sourcePage":"Period 7"},{"id":"apush-period-7-c10","front":"Great Depression","back":"The severe economic collapse beginning in 1929 that produced bank failures, unemployment, falling production, homelessness, and demands for a larger federal response to economic insecurity.","sourcePage":"Period 7"},{"id":"apush-period-7-c11","front":"New Deal","back":"Franklin D. Roosevelt’s programs and reforms addressing the Great Depression through relief for the unemployed, economic recovery measures, and long-term regulation and social insurance.","sourcePage":"Period 7"},{"id":"apush-period-7-c12","front":"United States in World War II","back":"The American mobilization after Pearl Harbor that combined military alliances, mass industrial production, scientific research, rationing, and expanded work opportunities to help defeat the Axis powers.","sourcePage":"Period 7"},{"id":"apush-period-7-c13","front":"Japanese American incarceration","back":"The forced removal and imprisonment of about 120,000 people of Japanese ancestry during World War II under Executive Order 9066, upheld at the time in Korematsu v. United States.","sourcePage":"Period 7"},{"id":"apush-period-7-c14","front":"Atomic bombings of Hiroshima and Nagasaki","back":"The August 1945 U.S. attacks that devastated two Japanese cities and accelerated Japan’s surrender while creating enduring debate over military necessity, civilian casualties, and nuclear warfare.","sourcePage":"Period 7"},{"id":"apush-period-7-c15","front":"Muckrakers","back":"Progressive journalists who exposed corruption, dangerous working conditions, corporate abuses, and urban poverty.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c16","front":"Pure Food and Drug Act","back":"The 1906 law prohibiting mislabeled or contaminated food and medicine and increasing federal consumer protection.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c17","front":"Meat Inspection Act","back":"The 1906 law establishing federal inspection and sanitation requirements in meatpacking.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c18","front":"Sixteenth Amendment","back":"The constitutional amendment authorizing a federal income tax.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c19","front":"Seventeenth Amendment","back":"The constitutional amendment establishing direct popular election of U.S. senators.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c20","front":"Nineteenth Amendment","back":"The constitutional amendment prohibiting denial of voting rights on the basis of sex.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c21","front":"Federal Reserve Act","back":"The 1913 law creating a central banking system to manage currency, credit, and financial stability.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c22","front":"Spanish-American War","back":"The 1898 conflict in Cuba and the Philippines that ended Spanish colonial rule and expanded U.S. overseas power.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c23","front":"Open Door Policy","back":"The U.S. policy advocating equal commercial access to China and preservation of Chinese territorial integrity.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c24","front":"Roosevelt Corollary","back":"The assertion that the United States could intervene in Latin American nations to preserve order and prevent European involvement.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c25","front":"Dollar Diplomacy","back":"The use of American investment and financial influence to advance U.S. strategic interests abroad.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c26","front":"Panama Canal","back":"The U.S.-built waterway opened in 1914 that linked the Atlantic and Pacific and strengthened American trade and naval power.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c27","front":"Fourteen Points","back":"Woodrow Wilson’s proposed principles for a postwar settlement emphasizing self-determination, open diplomacy, and a League of Nations.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c28","front":"Espionage and Sedition Acts","back":"World War I laws criminalizing interference with the war effort and certain criticism of the government, restricting civil liberties.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c29","front":"Schenck v. United States","back":"The 1919 Supreme Court decision upholding wartime speech restrictions and articulating the clear-and-present-danger standard.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c30","front":"Prohibition","back":"The national ban on producing and selling alcoholic beverages under the Eighteenth Amendment, later repealed by the Twenty-first Amendment.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c31","front":"Scopes trial","back":"The 1925 Tennessee trial over teaching evolution that symbolized conflict between modernism and religious fundamentalism.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c32","front":"Second Ku Klux Klan","back":"A revived nationwide organization promoting white Protestant supremacy and hostility toward Black Americans, Catholics, Jews, and immigrants.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c33","front":"Sacco and Vanzetti","back":"Italian immigrant anarchists whose controversial convictions and executions reflected nativism and fear of radicalism.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c34","front":"Fordism","back":"Mass production based on assembly lines, standardized goods, high output, and wages sufficient to support consumer purchasing.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c35","front":"Stock market crash of 1929","back":"The collapse in stock prices that damaged confidence and finance while helping expose deeper weaknesses leading into the Great Depression.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c36","front":"Dust Bowl","back":"Severe drought and soil erosion on the Great Plains that displaced farm families during the 1930s.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c37","front":"Social Security Act","back":"The 1935 law creating old-age pensions, unemployment insurance, and assistance programs through a federal-state system.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c38","front":"Wagner Act","back":"The 1935 law protecting collective bargaining and establishing the National Labor Relations Board.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c39","front":"Congress of Industrial Organizations","back":"A labor federation that organized mass-production workers across industries including steel and automobiles.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c40","front":"Court-packing plan","back":"Roosevelt’s unsuccessful proposal to add Supreme Court justices after the Court invalidated several New Deal programs.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c41","front":"Lend-Lease Act","back":"The 1941 law allowing the United States to supply military aid to nations considered vital to American defense.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c42","front":"Pearl Harbor","back":"The Japanese attack on December 7, 1941, that brought the United States into World War II.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c43","front":"Double V campaign","back":"The Black wartime campaign seeking victory over fascism abroad and racism at home.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c44","front":"Rosie the Riveter","back":"The cultural symbol of women entering industrial war work during World War II.","sourcePage":"CED Period 7"},{"id":"apush-period-7-c45","front":"Bracero Program","back":"A wartime agreement bringing Mexican laborers to the United States for temporary agricultural and railroad employment.","sourcePage":"CED Period 7"}],"questions":[],"feynmanPrompts":[{"id":"apush-period-7-f1","prompt":"The Progressive Era"},{"id":"apush-period-7-f2","prompt":"American imperialism"},{"id":"apush-period-7-f3","prompt":"The Great Depression and the New Deal"},{"id":"apush-period-7-f4","prompt":"World War II"},{"id":"apush-period-7-f5","prompt":"American society during the 1920s"}]},{"id":"apush-period-8","name":"AP U.S. History · Period 8: 1945–1980","shortName":"Period 8: 1945–1980","builtIn":true,"sourceTitle":"AP US History Flashcards by Time Period — APUSHReview","sourceUrl":"https://www.apushreview.com/additional-resources/ap-us-history-flashcards-by-time-period/","cards":[{"id":"apush-period-8-c1","front":"Containment","back":"The Cold War policy, associated with diplomat George Kennan, of resisting further expansion of Soviet influence and communism through economic, diplomatic, and military measures.","sourcePage":"Period 8"},{"id":"apush-period-8-c2","front":"Korean War","back":"The 1950–1953 conflict in which the United States and other United Nations forces defended South Korea against communist North Korea and Chinese intervention, ending near the original dividing line.","sourcePage":"Period 8"},{"id":"apush-period-8-c3","front":"Military-industrial complex","back":"The close relationship among the armed forces, government policymakers, and defense contractors whose influence President Eisenhower warned could encourage permanent military expansion.","sourcePage":"Period 8"},{"id":"apush-period-8-c4","front":"Baby boom","back":"The sharp rise in U.S. births from 1946 through 1964 that expanded demand for housing, schools, consumer goods, and later social programs.","sourcePage":"Period 8"},{"id":"apush-period-8-c5","front":"Postwar suburbanization","back":"The movement of millions of Americans to suburbs encouraged by automobiles, highways, federal mortgage policies, mass-produced housing such as Levittown, and racial exclusion from many developments.","sourcePage":"Period 8"},{"id":"apush-period-8-c6","front":"Civil rights activism","back":"Organized efforts using litigation, boycotts, sit-ins, Freedom Rides, marches, voter registration, and federal legislation to challenge segregation and racial discrimination.","sourcePage":"Period 8"},{"id":"apush-period-8-c7","front":"Brown v. Board of Education","back":"The 1954 Supreme Court decision declaring state-mandated segregation in public schools inherently unequal and overturning the educational basis of Plessy v. Ferguson.","sourcePage":"Period 8"},{"id":"apush-period-8-c8","front":"Sun Belt","back":"The growing region stretching from the Southeast through the Southwest to California that gained population, political influence, defense spending, and new industries after World War II.","sourcePage":"Period 8"},{"id":"apush-period-8-c9","front":"Great Society","back":"Lyndon B. Johnson’s domestic agenda that expanded the federal role in civil rights, health care, education, immigration, environmental protection, and the reduction of poverty.","sourcePage":"Period 8"},{"id":"apush-period-8-c10","front":"Immigration and Nationality Act of 1965","back":"The law that abolished the national-origins quota system and prioritized family reunification and skilled immigrants, increasing migration from Asia, Latin America, Africa, and the Caribbean.","sourcePage":"Period 8"},{"id":"apush-period-8-c11","front":"Vietnam War","back":"The prolonged conflict in which the United States supported South Vietnam against communist North Vietnam and the Viet Cong, provoking extensive domestic protest before U.S. withdrawal and communist victory.","sourcePage":"Period 8"},{"id":"apush-period-8-c12","front":"Counterculture","back":"A youth movement that rejected many conventional social norms, opposed the Vietnam War, experimented with communal living and drugs, and promoted sexual and cultural liberation.","sourcePage":"Period 8"},{"id":"apush-period-8-c13","front":"Détente","back":"The easing of Cold War tensions during the 1970s through negotiation and arms-control agreements, including SALT I, alongside improved U.S. relations with the Soviet Union and China.","sourcePage":"Period 8"},{"id":"apush-period-8-c14","front":"Modern environmental movement","back":"A broad campaign, energized by works such as Rachel Carson’s Silent Spring, that produced public pressure and federal measures including the EPA, Clean Air Act, and Clean Water Act.","sourcePage":"Period 8"},{"id":"apush-period-8-c15","front":"Truman Doctrine","back":"The 1947 commitment to support nations resisting communist pressure, first applied to Greece and Turkey.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c16","front":"Marshall Plan","back":"The U.S. program providing economic aid to rebuild Western Europe and limit communist influence after World War II.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c17","front":"North Atlantic Treaty Organization","back":"The collective-defense alliance formed in 1949 by the United States, Canada, and Western European nations.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c18","front":"Berlin Airlift","back":"The 1948–1949 operation supplying West Berlin by air during a Soviet blockade.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c19","front":"House Un-American Activities Committee","back":"A congressional committee that investigated alleged communist influence and contributed to blacklisting during the Second Red Scare.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c20","front":"McCarthyism","back":"The practice of making poorly supported accusations of communist disloyalty, associated with Senator Joseph McCarthy.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c21","front":"GI Bill","back":"The law providing veterans with education, housing, and business benefits that expanded the postwar middle class while being administered unequally.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c22","front":"Levittown","back":"A mass-produced suburban development that symbolized postwar homeownership and racially exclusionary housing practices.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c23","front":"Interstate Highway Act","back":"The 1956 law funding a national expressway system that promoted suburbanization, automobile travel, commerce, and urban displacement.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c24","front":"Montgomery bus boycott","back":"The 1955–1956 mass protest against segregated buses that elevated Martin Luther King Jr. and demonstrated sustained nonviolent activism.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c25","front":"Southern Christian Leadership Conference","back":"A civil rights organization led by Black ministers that coordinated nonviolent protest against segregation.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c26","front":"Student Nonviolent Coordinating Committee","back":"A youth-led civil rights organization central to sit-ins, Freedom Rides, voter registration, and grassroots organizing.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c27","front":"Freedom Rides","back":"Integrated interstate bus journeys in 1961 that challenged segregation and forced federal enforcement of desegregation rules.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c28","front":"March on Washington","back":"The 1963 demonstration for jobs and freedom where Martin Luther King Jr. delivered his “I Have a Dream” speech.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c29","front":"Civil Rights Act of 1964","back":"The law prohibiting discrimination in public accommodations and employment and strengthening federal enforcement against segregation.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c30","front":"Voting Rights Act of 1965","back":"The law banning discriminatory voting practices and authorizing federal oversight in jurisdictions with histories of exclusion.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c31","front":"Black Power","back":"A movement emphasizing racial pride, self-determination, community control, and sometimes armed self-defense.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c32","front":"Gulf of Tonkin Resolution","back":"The 1964 congressional measure granting President Johnson broad authority to escalate U.S. military involvement in Vietnam.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c33","front":"Tet Offensive","back":"The major 1968 communist assault that weakened American public confidence despite heavy military losses for North Vietnam and the Viet Cong.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c34","front":"Vietnamization","back":"Nixon’s policy of withdrawing U.S. troops while transferring more combat responsibility to South Vietnamese forces.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c35","front":"War Powers Resolution","back":"The 1973 law intended to limit unilateral presidential military action by requiring notification and congressional authorization.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c36","front":"Watergate","back":"The political scandal involving the Nixon administration’s cover-up of a break-in and abuses of power, leading to Nixon’s resignation.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c37","front":"New Frontier","back":"John F. Kennedy’s domestic program promoting economic growth, space exploration, social initiatives, and civil rights proposals.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c38","front":"Medicare and Medicaid","back":"Great Society programs providing health coverage respectively to older Americans and qualifying low-income people.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c39","front":"Stonewall uprising","back":"The 1969 resistance to a police raid at New York’s Stonewall Inn that became a catalyst for the modern LGBTQ rights movement.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c40","front":"National Organization for Women","back":"An organization founded in 1966 to pursue legal, political, and workplace equality for women.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c41","front":"Equal Rights Amendment","back":"A proposed constitutional amendment guaranteeing legal equality regardless of sex that fell short of ratification.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c42","front":"Silent Spring","back":"Rachel Carson’s 1962 book documenting pesticide harms and helping energize modern environmentalism.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c43","front":"Environmental Protection Agency","back":"The federal agency established in 1970 to enforce pollution standards and coordinate environmental regulation.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c44","front":"OPEC oil embargo","back":"The 1973 restriction on oil exports that produced fuel shortages, inflation, and heightened concern about U.S. energy dependence.","sourcePage":"CED Period 8"},{"id":"apush-period-8-c45","front":"Stagflation","back":"The combination of high inflation, weak economic growth, and unemployment that challenged conventional economic policy during the 1970s.","sourcePage":"CED Period 8"}],"questions":[],"feynmanPrompts":[{"id":"apush-period-8-f1","prompt":"The Cold War"},{"id":"apush-period-8-f2","prompt":"The Civil Rights Movement"},{"id":"apush-period-8-f3","prompt":"The Vietnam War and the antiwar movement"},{"id":"apush-period-8-f4","prompt":"Postwar prosperity and suburbanization"}]},{"id":"apush-period-9","name":"AP U.S. History · Period 9: 1980–Present","shortName":"Period 9: 1980–Present","builtIn":true,"sourceTitle":"AP US History Flashcards by Time Period — APUSHReview","sourceUrl":"https://www.apushreview.com/additional-resources/ap-us-history-flashcards-by-time-period/","cards":[{"id":"apush-period-9-c1","front":"Reaganomics","back":"The Reagan administration’s economic program emphasizing tax cuts, deregulation, reduced domestic spending, and increased defense spending, based partly on supply-side economic theory.","sourcePage":"Period 9"},{"id":"apush-period-9-c2","front":"Conservative opposition to big government","back":"The movement arguing that federal taxation, regulation, and social programs had grown too powerful, helping Ronald Reagan build a coalition around smaller government and traditional values.","sourcePage":"Period 9"},{"id":"apush-period-9-c3","front":"Reagan administration","back":"The presidency from 1981 to 1989 that advanced conservative economic policy, increased military spending, appointed conservative judges, and pursued a more confrontational early approach to the Soviet Union.","sourcePage":"Period 9"},{"id":"apush-period-9-c4","front":"Mikhail Gorbachev","back":"The final major leader of the Soviet Union, whose policies of glasnost and perestroika and negotiations with Ronald Reagan contributed to reduced Cold War tensions and the Soviet Union’s dissolution.","sourcePage":"Period 9"},{"id":"apush-period-9-c5","front":"September 11 attacks","back":"The 2001 al-Qaeda terrorist attacks on the World Trade Center and Pentagon that killed nearly 3,000 people and transformed U.S. foreign, military, immigration, and domestic-security policy.","sourcePage":"Period 9"},{"id":"apush-period-9-c6","front":"Wars in Afghanistan and Iraq","back":"Post-9/11 U.S. wars launched against the Taliban and al-Qaeda in Afghanistan and against Saddam Hussein’s government in Iraq; both developed into prolonged conflicts with extensive regional consequences.","sourcePage":"Period 9"},{"id":"apush-period-9-c7","front":"War on Terror","back":"The global U.S.-led campaign after September 11 using military action, intelligence, law enforcement, alliances, and expanded surveillance to combat terrorist organizations.","sourcePage":"Period 9"},{"id":"apush-period-9-c8","front":"Free-trade agreements","back":"Treaties such as NAFTA that reduced trade barriers among participating countries, increasing cross-border commerce while producing debate over jobs, wages, industry, and economic inequality.","sourcePage":"Period 9"},{"id":"apush-period-9-c9","front":"Climate change politics","back":"The growing political dispute over greenhouse-gas emissions, energy policy, environmental regulation, scientific evidence, and the proper national and international response to global warming.","sourcePage":"Period 9"},{"id":"apush-period-9-c10","front":"New Right","back":"A conservative coalition of religious activists, anticommunists, business interests, and voters opposed to taxes, regulation, and liberal social policy.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c11","front":"Moral Majority","back":"A conservative Christian political organization that mobilized evangelical voters around social issues and Republican candidates.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c12","front":"Supply-side economics","back":"The theory that reducing taxes and regulation encourages investment, production, and economic growth.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c13","front":"Strategic Defense Initiative","back":"Reagan’s proposed missile-defense system intended to protect the United States from nuclear attack.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c14","front":"Iran-Contra affair","back":"The scandal in which officials secretly sold arms to Iran and directed proceeds to Contra rebels despite congressional restrictions.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c15","front":"Glasnost","back":"Gorbachev’s policy of greater openness in Soviet government and public discussion.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c16","front":"Perestroika","back":"Gorbachev’s effort to restructure the Soviet political and economic system.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c17","front":"Fall of the Berlin Wall","back":"The 1989 opening and dismantling of the barrier dividing Berlin, symbolizing the collapse of communist rule in Eastern Europe.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c18","front":"Persian Gulf War","back":"The 1991 U.S.-led military campaign that expelled Iraqi forces from Kuwait.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c19","front":"North American Free Trade Agreement","back":"The 1994 agreement reducing trade barriers among the United States, Canada, and Mexico.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c20","front":"World Trade Organization","back":"The international body created in 1995 to administer trade agreements and resolve disputes among member nations.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c21","front":"Globalization","back":"The increasing international integration of markets, production, finance, communication, migration, and culture.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c22","front":"Deindustrialization","back":"The decline or relocation of manufacturing employment that transformed many American communities and labor markets.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c23","front":"Rust Belt","back":"The industrial region of the Northeast and Midwest affected by factory closures, job losses, and population decline.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c24","front":"Information Revolution","back":"The economic and social transformation driven by computers, digital communication, the internet, and knowledge-based industries.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c25","front":"Personal Responsibility and Work Opportunity Reconciliation Act","back":"The 1996 welfare law replacing a federal entitlement with time-limited state-administered assistance tied to work requirements.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c26","front":"Election of 2000","back":"The disputed presidential contest resolved after Bush v. Gore halted a Florida recount, giving George W. Bush the presidency.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c27","front":"USA PATRIOT Act","back":"The post-9/11 law expanding federal surveillance, investigation, and information-sharing powers in terrorism cases.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c28","front":"Department of Homeland Security","back":"The cabinet department created after September 11 to coordinate domestic security, border, emergency, and counterterrorism functions.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c29","front":"Bush Doctrine","back":"The foreign-policy approach asserting a right to preventive action against perceived threats and states supporting terrorism.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c30","front":"Great Recession","back":"The severe 2007–2009 economic downturn triggered by a housing and financial crisis, producing unemployment, foreclosures, and federal intervention.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c31","front":"Troubled Asset Relief Program","back":"The 2008 program authorizing federal funds to stabilize banks and financial markets during the crisis.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c32","front":"Affordable Care Act","back":"The 2010 law expanding health-insurance coverage through marketplaces, subsidies, Medicaid expansion, and insurance regulations.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c33","front":"Deferred Action for Childhood Arrivals","back":"The 2012 policy offering renewable protection from deportation and work authorization to some immigrants brought to the United States as children.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c34","front":"Tea Party movement","back":"A conservative movement opposing taxes, federal spending, the Affordable Care Act, and what it viewed as excessive government power.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c35","front":"Black Lives Matter","back":"A movement founded in 2013 that protests police violence and broader forms of systemic racism.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c36","front":"Same-sex marriage","back":"A major civil-rights issue culminating in the 2015 Obergefell v. Hodges decision recognizing a constitutional right to marriage for same-sex couples.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c37","front":"Obergefell v. Hodges","back":"The 2015 Supreme Court decision requiring states to license and recognize marriages between two people of the same sex.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c38","front":"Citizens United v. FEC","back":"The 2010 Supreme Court decision holding that independent political spending by corporations and unions is protected speech.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c39","front":"Demographic change","back":"The transformation of the U.S. population through immigration, aging, regional movement, and growing racial and ethnic diversity.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c40","front":"Immigration Reform and Control Act","back":"The 1986 law granting legal status to many undocumented immigrants while penalizing employers who knowingly hired unauthorized workers.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c41","front":"North American migration after 1980","back":"Continued immigration from Latin America, Asia, Africa, and the Caribbean that reshaped communities, politics, labor, and culture.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c42","front":"Election of Barack Obama","back":"The 2008 election of the first African American president amid economic crisis and wars in Iraq and Afghanistan.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c43","front":"Polarization","back":"The widening ideological distance between political parties and their voters, accompanied by declining bipartisan cooperation.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c44","front":"War on drugs","back":"Federal and state policies emphasizing criminal enforcement against illegal drugs, contributing to expanded incarceration and racial disparities.","sourcePage":"CED Period 9"},{"id":"apush-period-9-c45","front":"Mass incarceration","back":"The dramatic growth of the U.S. prison population since the late twentieth century, driven by sentencing policy, drug enforcement, and unequal impacts.","sourcePage":"CED Period 9"}],"questions":[],"feynmanPrompts":[{"id":"apush-period-9-f1","prompt":"The conservative resurgence"},{"id":"apush-period-9-f2","prompt":"Globalization and deindustrialization"},{"id":"apush-period-9-f3","prompt":"The War on Terror"},{"id":"apush-period-9-f4","prompt":"Immigration and demographic change"}]}];
